window.__TNPSC_REGISTER_TEST__("gk", 4, [{"id":301,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பு நிர்ணய சபை எந்தத் திட்டத்தின் பரிந்துரையின் அடிப்படையில் 1946-ஆம் ஆண்டு உருவாக்கப்பட்டது?","options":["வேவல் திட்டம்","மவுண்ட்பேட்டன் திட்டம்","அமைச்சரவைத் தூதுக்குழுத் திட்டம்","கிரிப்ஸ் தூதுக்குழுத் திட்டம்"],"correctAnswer":2,"explanation":"1946-ஆம் ஆண்டு இந்தியா வந்த அமைச்சரவைத் தூதுக்குழுத் (Cabinet Mission Plan) திட்டத்தின் பரிந்துரையின் அடிப்படையில் இந்திய அரசியலமைப்பு நிர்ணய சபை உருவாக்கப்பட்டது. இச்சபையின் மொத்த உறுப்பினர்கள் எண்ணிக்கை தொடக்கத்தில் 389 ஆக இருந்தது.","difficulty":"easy","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":302,"subject":"gk","testNumber":4,"question":"1946 டிசம்பர் 9-ஆம் நாள் நடைபெற்ற இந்திய அரசியலமைப்பு நிர்ணய சபையின் முதல் கூட்டத்திற்குத் தற்காலிகத் தலைவராகத் தேர்ந்தெடுக்கப்பட்டவர் யார்?","options":["டாக்டர் ராஜேந்திர பிரசாத்","ஜவஹர்லால் நேரு","எச்.சி. முகர்ஜி","டாக்டர் சச்சிதானந்த சின்ஹா"],"correctAnswer":3,"explanation":"அரசியலமைப்பு நிர்ணய சபையின் முதல் கூட்டம் 1946 டிசம்பர் 9-ஆம் நாள் நடைபெற்றது. பிரெஞ்சு நடைமுறையைப் பின்பற்றி அச்சபையின் மூத்த உறுப்பினரான டாக்டர் சச்சிதானந்த சின்ஹா தற்காலிகத் தலைவராகத் தேர்ந்தெடுக்கப்பட்டார்.","difficulty":"easy","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":303,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பு நிர்ணய சபையின் நிரந்தரத் தலைவராகத் தேர்ந்தெடுக்கப்பட்டவர் யார்?","options":["சி. ராஜகோபாலாச்சாரி","சர்தார் வல்லபாய் படேல்","டாக்டர் பி.ஆர். அம்பேத்கர்","டாக்டர் ராஜேந்திர பிரசாத்"],"correctAnswer":3,"explanation":"1946 டிசம்பர் 11-ஆம் நாள் டாக்டர் ராஜேந்திர பிரசாத் அரசியலமைப்பு நிர்ணய சபையின் நிரந்தரத் தலைவராகத் தேர்ந்தெடுக்கப்பட்டார். எச்.சி. முகர்ஜி மற்றும் வி.டி. கிருஷ்ணமாச்சாரி ஆகியோர் துணைத் தலைவர்களாகத் தேர்ந்தெடுக்கப்பட்டனர்.","difficulty":"easy","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":304,"subject":"gk","testNumber":4,"question":"டாக்டர் பி.ஆர். அம்பேத்கர் தலைமையில் அமைக்கப்பட்ட அரசியலமைப்பு வரைவுக் குழுவில் (Drafting Committee) தலைவர் உட்பட எத்தனை உறுப்பினர்கள் இருந்தனர்?","options":["6 உறுப்பினர்கள்","7 உறுப்பினர்கள்","5 உறுப்பினர்கள்","9 உறுப்பினர்கள்"],"correctAnswer":1,"explanation":"1947 ஆகஸ்ட் 29-ஆம் நாள் டாக்டர் பி.ஆர். அம்பேத்கர் தலைமையில் 7 உறுப்பினர்களைக் கொண்ட வரைவுக் குழு அமைக்கப்பட்டது. டாக்டர் அம்பேத்கர் 'இந்திய அரசியலமைப்பின் தந்தை' என அழைக்கப்படுகிறார்.","difficulty":"easy","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":305,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பு நிர்ணய சபையால் இந்திய அரசியலமைப்பு ஏற்றுக்கொள்ளப்பட்ட நாள் எது?","options":["1949 நவம்பர் 26","1950 ஜனவரி 26","1947 ஆகஸ்ட் 15","1949 டிசம்பர் 26"],"correctAnswer":0,"explanation":"இந்திய அரசியலமைப்பு 2 ஆண்டுகள் 11 மாதங்கள் 18 நாட்கள் உழைப்பிற்குப் பின் 1949 நவம்பர் 26-ஆம் நாள் ஏற்றுக்கொள்ளப்பட்டது. இதனை நினைவுகூரும் வகையில் ஒவ்வொரு ஆண்டும் நவம்பர் 26 'அரசியலமைப்பு தினமாக' கொண்டாடப்படுகிறது.","difficulty":"easy","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":306,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பு 1950 ஜனவரி 26-ஆம் நாள் நடைமுறைக்கு வருவதற்குத் தேர்ந்தெடுக்கப்பட்டதன் வரலாற்றுக் காரணம் என்ன?","options":["வெள்ளையனே வெளியேறு இயக்கம் தொடங்கிய நாள்","அரசியலமைப்பு நிர்ணய சபை முதல் கூட்டம் நடைபெற்ற நாள்","இந்தியா விடுதலை அடைந்த ஒப்பந்தம் கையெழுத்தான நாள்","1930 ஜனவரி 26-ஆம் நாள் பூரண சுயராஜ்ஜிய தினமாகக் கொண்டாடப்பட்டதால்"],"correctAnswer":3,"explanation":"1929-ஆம் ஆண்டு நடைபெற்ற லாகூர் இந்திய தேசிய காங்கிரஸ் மாநாட்டில் 'பூரண சுயராஜ்ஜியம்' (முழு சுதந்திரம்) தீர்மானம் நிறைவேற்றப்பட்டு, 1930 ஜனவரி 26 முழு சுதந்திர நாளாகக் கொண்டாடப்பட்டது. அந்த வரலாற்று நாளைச் சிறப்பிக்கவே 1950 ஜனவரி 26 அன்று அரசியலமைப்பு நடைமுறைப்படுத்தப்பட்டு குடியரசு தினமாகக் கொண்டாடப்படுகிறது.","difficulty":"medium","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":307,"subject":"gk","testNumber":4,"question":"1946 டிசம்பர் 13-ஆம் நாள் அரசியலமைப்பு நிர்ணய சபையில் 'குறிக்கோள் தீர்மானத்தை' (Objectives Resolution) முன்மொழிந்தவர் யார்?","options":["சர்தார் வல்லபாய் படேல்","ஜவஹர்லால் நேரு","மகாத்மா காந்தி","டாக்டர் பி.ஆர். அம்பேத்கர்"],"correctAnswer":1,"explanation":"ஜவஹர்லால் நேரு 1946 டிசம்பர் 13-ஆம் நாள் அரசியலமைப்பு நிர்ணய சபையில் 'குறிக்கோள் தீர்மானத்தை' முன்மொழிந்தார். இத்தீர்மானம் 1947 ஜனவரி 22-ஆம் நாள் ஏற்றுக்கொள்ளப்பட்டு, பின்னர் இந்திய அரசியலமைப்பின் முகவுரைக்கு அடிப்படையாக அமைந்தது.","difficulty":"medium","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":308,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பு நிர்ணய சபையின் சட்ட ஆலோசகராக (Constitutional Advisor) பணியாற்றியவர் யார்?","options":["பி.என். ராவ்","கே.எம். முன்ஷி","அல்லாடி கிருஷ்ணசாமி ஐயர்","என். கோபாலசாமி ஐயங்கார்"],"correctAnswer":0,"explanation":"சர் பி.என். ராவ் (பெனகல் நரசிங்க ராவ்) இந்திய அரசியலமைப்பு நிர்ணய சபையின் சட்ட ஆலோசகராகப் பணியாற்றினார். இவர் பல நாடுகளின் அரசியலமைப்புகளை ஆய்வு செய்து முதல் வரைவைத் தயாரிக்கப் பெரிதும் உதவினார்.","difficulty":"medium","topic":"அரசியலமைப்பு உருவாக்கம்"},{"id":309,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பில் உள்ள 'நாடாளுமன்ற ஆட்சி முறை' மற்றும் 'ஒற்றைக் குடியுரிமை' ஆகிய அம்சங்கள் எந்த நாட்டின் அரசியலமைப்பிலிருந்து பெறப்பட்டன?","options":["கனடா","ஆஸ்திரேலியா","அமெரிக்க ஐக்கிய நாடுகள்","இங்கிலாந்து (பிரிட்டன்)"],"correctAnswer":3,"explanation":"நாடாளுமன்ற ஆட்சி முறை, ஒற்றைக் குடியுரிமை, சட்டத்தின் ஆட்சி (Rule of Law), அமைச்சரவை முறை மற்றும் ஈரவை நாடாளுமன்றம் ஆகிய அம்சங்கள் இங்கிலாந்து (பிரிட்டன்) அரசியலமைப்பிலிருந்து பெறப்பட்டன.","difficulty":"easy","topic":"அரசியலமைப்பின் சிறப்பு அம்சங்கள்"},{"id":310,"subject":"gk","testNumber":4,"question":"வலிமையான மத்திய அரசுடன் கூடிய கூட்டாட்சி முறை மற்றும் எஞ்சிய அதிகாரங்கள் (Residuary Powers) மத்திய அரசிடம் இருத்தல் ஆகிய அம்சங்கள் எந்த நாட்டிலிருந்து பெறப்பட்டன?","options":["ஜெர்மனி","அமெரிக்க ஐக்கிய நாடுகள்","பிரான்ஸ்","கனடா"],"correctAnswer":3,"explanation":"வலிமையான மத்திய அரசுடன் கூடிய கூட்டாட்சி முறை, எஞ்சிய அதிகாரங்கள் மத்திய அரசிடம் ஒப்படைக்கப்படுதல் மற்றும் மாநில ஆளுநர்களை மத்திய அரசு நியமித்தல் ஆகிய அம்சங்கள் கனடா நாட்டு அரசியலமைப்பிலிருந்து பெறப்பட்டன.","difficulty":"medium","topic":"அரசியலமைப்பின் சிறப்பு அம்சங்கள்"},{"id":311,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்புச் சட்டத்திருத்த நடைமுறை (Procedure for Amendment of the Constitution) எந்த நாட்டின் அரசியலமைப்பிலிருந்து பெறப்பட்டது?","options":["தென்னாப்பிரிக்கா","சோவியத் ரஷ்யா","ஜப்பான்","அயர்லாந்து"],"correctAnswer":0,"explanation":"இந்திய அரசியலமைப்பைத் திருத்தும் முறை மற்றும் மாநிலங்களவை உறுப்பினர்களைத் தேர்ந்தெடுக்கும் முறை ஆகியவை தென்னாப்பிரிக்கா நாட்டின் அரசியலமைப்பிலிருந்து பெறப்பட்டன. இவை அரசியலமைப்பின் பகுதி XX, சட்டப்பிரிவு 368-இல் இடம்பெற்றுள்ளன.","difficulty":"medium","topic":"அரசியலமைப்பின் சிறப்பு அம்சங்கள்"},{"id":312,"subject":"gk","testNumber":4,"question":"அடிப்படை உரிமைகள், நீதிப்புனராய்வு மற்றும் சுதந்திரமான நீதித்துறை ஆகிய முக்கிய அம்சங்கள் எந்த நாட்டின் அரசியலமைப்பிலிருந்து பெறப்பட்டன?","options":["பிரான்ஸ்","அமெரிக்க ஐக்கிய நாடுகள்","ஆஸ்திரேலியா","இங்கிலாந்து"],"correctAnswer":1,"explanation":"அடிப்படை உரிமைகள், நீதிப்புனராய்வு (Judicial Review), சுதந்திரமான நீதித்துறை, குடியரசுத் தலைவர் மீதான பதவி நீக்க நடைமுறை மற்றும் துணைக் குடியரசுத் தலைவர் பதவி ஆகியவை அமெரிக்க ஐக்கிய நாடுகளின் அரசியலமைப்பிலிருந்து பெறப்பட்டன.","difficulty":"easy","topic":"அரசியலமைப்பின் சிறப்பு அம்சங்கள்"},{"id":313,"subject":"gk","testNumber":4,"question":"1976-ஆம் ஆண்டு 42-ஆவது அரசியலமைப்புச் சட்டத்திருத்தத்தின் மூலம் முகவுரையில் புதிதாகச் சேர்க்கப்பட்ட மூன்று சொற்கள் எவை?","options":["நீதி, சுதந்திரம், சமத்துவம்","இறையாண்மை, மக்களாட்சி, குடியரசு","சமதர்ம, சமயச்சார்பற்ற, ஒருமைப்பாடு","சகோதரத்துவம், ஒற்றுமை, சமதர்ம"],"correctAnswer":2,"explanation":"இந்திய அரசியலமைப்பின் முகவுரை இதுவரை ஒருமுறை மட்டுமே 1976-ஆம் ஆண்டு 42-ஆவது சட்டத்திருத்தத்தின் மூலம் திருத்தப்பட்டுள்ளது. இத்திருத்தத்தின் மூலம் 'சமதர்ம' (Socialist), 'சமயச்சார்பற்ற' (Secular) மற்றும் 'ஒருமைப்பாடு' (Integrity) ஆகிய மூன்று சொற்கள் சேர்க்கப்பட்டன.","difficulty":"easy","topic":"முகவுரை"},{"id":314,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பின் முகவுரையில் இடம்பெற்றுள்ள 'சுதந்திரம், சமத்துவம், சகோதரத்துவம்' என்ற கொள்கைகள் எந்த வரலாற்றுப் புரட்சியிலிருந்து பெறப்பட்டன?","options":["இங்கிலாந்து மகத்தான புரட்சி (1688)","ரஷ்யப் புரட்சி (1917)","அமெரிக்கப் புரட்சி (1776)","பிரெஞ்சுப் புரட்சி (1789)"],"correctAnswer":3,"explanation":"1789-ஆம் ஆண்டு நடைபெற்ற பிரெஞ்சுப் புரட்சியின் முக்கிய முழக்கங்களான 'சுதந்திரம், சமத்துவம், சகோதரத்துவம்' (Liberty, Equality, Fraternity) மற்றும் குடியரசுக் கொள்கை ஆகியவை இந்திய அரசியலமைப்பின் முகவுரையில் சேர்க்கப்பட்டுள்ளன.","difficulty":"medium","topic":"முகவுரை"},{"id":315,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பின் முகவுரையை 'அரசியலமைப்பின் அடையாள அட்டை' (Identity Card of the Constitution) என்று குறிப்பிட்ட சட்ட நிபுணர் யார்?","options":["என்.ஏ. பால்கிவாலா","கே.எம். முன்ஷி","சர் எர்னஸ்ட் பார்கர்","ததாகூர் தாஸ் பார்கவா"],"correctAnswer":0,"explanation":"புகழ்பெற்ற அரசியலமைப்புச் சட்ட நிபுணரான என்.ஏ. பால்கிவாலா முகவுரையை 'அரசியலமைப்பின் அடையாள அட்டை' என்று வர்ணித்தார். கே.எம். முன்ஷி இதனை 'இறையாண்மை கொண்ட மக்களாட்சிக் குடியரசின் ஜாதகம்' என்று குறிப்பிட்டார்.","difficulty":"hard","topic":"முகவுரை"},{"id":316,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பின் 8-ஆவது அட்டவணை எதைப் பற்றிக் குறிப்பிடுகிறது?","options":["பஞ்சாயத்து அமைப்புகளின் அதிகாரங்கள்","மத்திய-மாநில அதிகாரப் பகிர்வு","அரசியலமைப்பால் அங்கீகரிக்கப்பட்ட மொழிகள்","மாநிலங்கள் மற்றும் யூனியன் பிரதேசங்களின் பெயர்கள்"],"correctAnswer":2,"explanation":"இந்திய அரசியலமைப்பின் 8-ஆவது அட்டவணை அங்கீகரிக்கப்பட்ட மொழிகளைப் பற்றிக் கூறுகிறது. அரசியலமைப்பு நடைமுறைக்கு வந்தபோது இதில் 14 மொழிகள் இருந்தன; தற்போது பல்வேறு சட்டத்திருத்தங்களுக்குப் பிறகு 22 மொழிகள் இடம்பெற்றுள்ளன.","difficulty":"easy","topic":"அட்டவணைகள் மற்றும் பகுதிகள்"},{"id":317,"subject":"gk","testNumber":4,"question":"1985-ஆம் ஆண்டு 52-ஆவது சட்டத்திருத்தத்தின் மூலம் சேர்க்கப்பட்ட கட்சித் தாவல் தடைச் சட்டம் (Anti-Defection Law) எந்த அட்டவணையில் உள்ளது?","options":["10-ஆவது அட்டவணை","11-ஆவது அட்டவணை","12-ஆவது அட்டவணை","9-ஆவது அட்டவணை"],"correctAnswer":0,"explanation":"1985-ஆம் ஆண்டு 52-ஆவது அரசியலமைப்புச் சட்டத்திருத்தத்தின் மூலம் 10-ஆவது அட்டவணை சேர்க்கப்பட்டது. இது நாடாளுமன்றம் மற்றும் மாநில சட்டமன்ற உறுப்பினர்கள் கட்சித் தாவல் செய்தால் தகுதி நீக்கம் செய்வதற்கான விதிகளைக் கொண்டுள்ளது.","difficulty":"medium","topic":"அட்டவணைகள் மற்றும் பகுதிகள்"},{"id":318,"subject":"gk","testNumber":4,"question":"மத்தியப் பட்டியல், மாநிலப் பட்டியல் மற்றும் பொதுப் பட்டியல் ஆகிய மூன்று அதிகாரப் பட்டியல்களும் எந்த அட்டவணையில் இடம்பெற்றுள்ளன?","options":["5-ஆவது அட்டவணை","7-ஆவது அட்டவணை","6-ஆவது அட்டவணை","9-ஆவது அட்டவணை"],"correctAnswer":1,"explanation":"மத்திய மற்றும் மாநில அரசுகளுக்கு இடையிலான சட்டமியற்றும் அதிகாரப் பகிர்வு 7-ஆவது அட்டவணையில் மூன்று பட்டியல்களாகப் பிரிக்கப்பட்டுள்ளது. தொடக்கத்தில் மத்தியப் பட்டியலில் 97, மாநிலப் பட்டியலில் 66, பொதுப் பட்டியலில் 47 துறைகள் இருந்தன.","difficulty":"medium","topic":"அட்டவணைகள் மற்றும் பகுதிகள்"},{"id":319,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பில் 'குடியுரிமை' (Citizenship) பற்றிய விதிகள் எந்தப் பகுதி மற்றும் சட்டப்பிரிவுகளில் இடம்பெற்றுள்ளன?","options":["பகுதி I, சட்டப்பிரிவுகள் 1 முதல் 4 வரை","பகுதி II, சட்டப்பிரிவுகள் 5 முதல் 11 வரை","பகுதி IV, சட்டப்பிரிவுகள் 36 முதல் 51 வரை","பகுதி III, சட்டப்பிரிவுகள் 12 முதல் 35 வரை"],"correctAnswer":1,"explanation":"இந்திய அரசியலமைப்பின் பகுதி II-இல் சட்டப்பிரிவுகள் 5 முதல் 11 வரை குடியுரிமை குறித்த விதிகள் உள்ளன. இந்திய அரசியலமைப்பு நாடு முழுவதற்கும் 'ஒற்றைக் குடியுரிமை' முறையை வழங்குகிறது.","difficulty":"easy","topic":"குடியுரிமை"},{"id":320,"subject":"gk","testNumber":4,"question":"1955-ஆம் ஆண்டு இந்தியக் குடியுரிமைச் சட்டத்தின்படி, முறையே எத்தனை வழிகளில் இந்தியக் குடியுரிமையைப் பெறலாம் மற்றும் எத்தனை வழிகளில் இழக்கலாம்?","options":["5 வழிகளில் பெறலாம், 3 வழிகளில் இழக்கலாம்","4 வழிகளில் பெறலாம், 2 வழிகளில் இழக்கலாம்","6 வழிகளில் பெறலாம், 4 வழிகளில் இழக்கலாம்","3 வழிகளில் பெறலாம், 5 வழிகளில் இழக்கலாம்"],"correctAnswer":0,"explanation":"1955-ஆம் ஆண்டு குடியுரிமைச் சட்டத்தின்படி பிறப்பு, வம்சாவளி, பதிவு செய்தல், இயல்புரிமை மற்றும் பிரதேச இணைப்பு ஆகிய 5 வழிகளில் குடியுரிமை பெறலாம். அதேபோல் துறத்தல், முடிவுறச் செய்தல் மற்றும் இழத்தல் ஆகிய 3 வழிகளில் குடியுரிமை இழக்கப்படலாம்.","difficulty":"hard","topic":"குடியுரிமை"},{"id":321,"subject":"gk","testNumber":4,"question":"'இந்தியாவின் மகாசாசனம்' (Magna Carta of India) என்று அழைக்கப்படும் அடிப்படை உரிமைகள் அரசியலமைப்பின் எந்தப் பகுதியில் இடம்பெற்றுள்ளன?","options":["பகுதி IV (சட்டப்பிரிவுகள் 36 முதல் 51 வரை)","பகுதி II (சட்டப்பிரிவுகள் 5 முதல் 11 வரை)","பகுதி IVA (சட்டப்பிரிவு 51A)","பகுதி III (சட்டப்பிரிவுகள் 12 முதல் 35 வரை)"],"correctAnswer":3,"explanation":"அடிப்படை உரிமைகள் இந்திய அரசியலமைப்பின் பகுதி III-இல் சட்டப்பிரிவுகள் 12 முதல் 35 வரை இடம்பெற்றுள்ளன. குடிமக்களின் அடிப்படை உரிமைகளைப் பாதுகாப்பதால் இப்பகுதி 'இந்தியாவின் மகாசாசனம்' எனப் போற்றப்படுகிறது.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":322,"subject":"gk","testNumber":4,"question":"தீண்டாமையை ஒழித்து, அதை எந்த வடிவத்திலும் பின்பற்றுவதைத் தடை செய்யும் இந்திய அரசியலமைப்புச் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 15","சட்டப்பிரிவு 16","சட்டப்பிரிவு 18","சட்டப்பிரிவு 17"],"correctAnswer":3,"explanation":"சமத்துவ உரிமையின் கீழ் வரும் சட்டப்பிரிவு 17 தீண்டாமையை முழுமையாக ஒழிக்கிறது. தீண்டாமையைக் கடைப்பிடிப்பது சட்டப்படி தண்டனைக்குரிய குற்றமாக அறிவிக்கப்பட்டுள்ளது.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":323,"subject":"gk","testNumber":4,"question":"'சட்டத்தின் முன் அனைவரும் சமம்' மற்றும் 'சட்டங்களின் சம பாதுகாப்பு' ஆகியவற்றை வழங்கும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 14","சட்டப்பிரிவு 12","சட்டப்பிரிவு 19","சட்டப்பிரிவு 13"],"correctAnswer":0,"explanation":"சட்டப்பிரிவு 14 இந்திய எல்லைக்குள் உள்ள அனைவருக்கும் சட்டத்தின் முன் சமத்துவத்தையும் சட்டங்களின் சம பாதுகாப்பையும் உறுதி செய்கிறது. இது இந்தியக் குடிமக்கள் மற்றும் வெளிநாட்டவர் இருவருக்கும் பொருந்தும்.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":324,"subject":"gk","testNumber":4,"question":"ராணுவம் மற்றும் கல்விசார் பட்டங்கள் தவிர பிற பட்டங்களை அரசு வழங்குவதைத் தடை செய்யும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 15","சட்டப்பிரிவு 17","சட்டப்பிரிவு 16","சட்டப்பிரிவு 18"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 18-இன்படி ராணுவம் மற்றும் கல்விசார் பட்டங்களைத் தவிர மற்ற பரம்பரைப் பட்டங்கள் போன்றவற்றை அரசு வழங்கக் கூடாது. பாரத ரத்னா, பத்ம விருதுகள் போன்றவை சிறப்பு அங்கீகார விருதுகளே தவிர பட்டங்கள் அல்ல என உச்ச நீதிமன்றம் தீர்ப்பளித்துள்ளது.","difficulty":"medium","topic":"அடிப்படை உரிமைகள்"},{"id":325,"subject":"gk","testNumber":4,"question":"மதம், இனம், சாதி, பாலினம் மற்றும் பிறப்பிடம் ஆகியவற்றின் அடிப்படையில் அரசு குடிமக்களிடையே பாகுபாடு காட்டுவதைத் தடை செய்யும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 15","சட்டப்பிரிவு 29","சட்டப்பிரிவு 20","சட்டப்பிரிவு 16"],"correctAnswer":0,"explanation":"சட்டப்பிரிவு 15 மதம், இனம், சாதி, பாலினம் அல்லது பிறப்பிடம் என்ற காரணங்களுக்காக எந்தவொரு குடிமகனுக்கும் எதிராக அரசு பாகுபாடு காட்டக் கூடாது எனக் கூறுகிறது. பொது இடங்களை அனைவரும் சமமாகப் பயன்படுத்த இச்சட்டப்பிரிவு வழிவகுக்கிறது.","difficulty":"medium","topic":"அடிப்படை உரிமைகள்"},{"id":326,"subject":"gk","testNumber":4,"question":"பேச்சு மற்றும் கருத்து வெளிப்பாட்டுச் சுதந்திரம், அமைதியாகக் கூடும் சுதந்திரம், சங்கம் அமைக்கும் சுதந்திரம் உள்ளிட்ட ஆறு அடிப்படைச் சுதந்திரங்களை வழங்கும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 21","சட்டப்பிரிவு 19","சட்டப்பிரிவு 22","சட்டப்பிரிவு 18"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 19 இந்தியக் குடிமக்களுக்கு ஆறு வகையான அடிப்படைச் சுதந்திரங்களை வழங்குகிறது. அவை பேச்சு சுதந்திரம், ஆயுதமின்றி அமைதியாகக் கூடும் சுதந்திரம், சங்கம் அமைக்கும் சுதந்திரம், இந்தியாவில் எங்கும் செல்லும் சுதந்திரம், வசிக்கும் சுதந்திரம் மற்றும் விரும்பிய தொழிலைச் செய்யும் சுதந்திரம் ஆகியனவாகும்.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":327,"subject":"gk","testNumber":4,"question":"சட்டத்தால் நிறுவப்பட்ட நடைமுறையின்படி அன்றி எவருடைய உயிரையும் தனிப்பட்ட சுதந்திரத்தையும் பறிக்கக் கூடாது என்று கூறும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 20","சட்டப்பிரிவு 21","சட்டப்பிரிவு 19","சட்டப்பிரிவு 22"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 21 வாழ்க்கை மற்றும் தனிப்பட்ட சுதந்திரத்திற்கான பாதுகாப்பை வழங்குகிறது. தேசிய அவசரநிலை அமலில் இருக்கும்போது கூட சட்டப்பிரிவுகள் 20 மற்றும் 21 ஆகியவற்றை நிறுத்தி வைக்க முடியாது.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":328,"subject":"gk","testNumber":4,"question":"6 முதல் 14 வயது வரையிலான அனைத்துக் குழந்தைகளுக்கும் இலவச மற்றும் கட்டாயக் கல்வியை அடிப்படை உரிமையாக வழங்கும் சட்டப்பிரிவு 21A எந்தச் சட்டத்திருத்தத்தின் மூலம் சேர்க்கப்பட்டது?","options":["73-ஆவது சட்டத்திருத்தம் (1992)","44-ஆவது சட்டத்திருத்தம் (1978)","86-ஆவது சட்டத்திருத்தம் (2002)","42-ஆவது சட்டத்திருத்தம் (1976)"],"correctAnswer":2,"explanation":"2002-ஆம் ஆண்டு 86-ஆவது அரசியலமைப்புச் சட்டத்திருத்தத்தின் மூலம் சட்டப்பிரிவு 21A சேர்க்கப்பட்டு, 6 முதல் 14 வயது வரையிலான குழந்தைகளுக்குத் தொடக்கக் கல்வி அடிப்படை உரிமையாக்கப்பட்டது. இதன் அடிப்படையில் 2009-ஆம் ஆண்டு கல்வி உரிமைச் சட்டம் (RTE) இயற்றப்பட்டது.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":329,"subject":"gk","testNumber":4,"question":"14 வயதுக்குட்பட்ட குழந்தைகளைத் தொழிற்சாலைகள், சுரங்கங்கள் மற்றும் ஆபத்தான பணிகளில் ஈடுபடுத்துவதைத் தடை செய்யும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 23","சட்டப்பிரிவு 24","சட்டப்பிரிவு 22","சட்டப்பிரிவு 25"],"correctAnswer":1,"explanation":"சுரண்டலுக்கு எதிரான உரிமையின் கீழ் வரும் சட்டப்பிரிவு 24 குழந்தைத் தொழிலாளர் முறையைத் தடை செய்கிறது. 14 வயதுக்குட்பட்ட குழந்தைகளைத் தொழிற்சாலைகள், சுரங்கங்கள் அல்லது பிற ஆபத்தான பணிகளில் அமர்த்துவது சட்டப்படி குற்றமாகும்.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":330,"subject":"gk","testNumber":4,"question":"மனிதர்களை வணிகம் செய்தல் மற்றும் கட்டாய வேலை (கொத்தடிமை முறை) ஆகியவற்றைத் தடை செய்யும் அரசியலமைப்புச் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 22","சட்டப்பிரிவு 26","சட்டப்பிரிவு 24","சட்டப்பிரிவு 23"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 23 மனிதர்களை விற்பனை செய்தல், கட்டாய வேலை வாங்குதல் (Begar) மற்றும் கொத்தடிமை முறை போன்ற அனைத்துச் சுரண்டல்களையும் தடை செய்கிறது. இது இந்தியக் குடிமக்கள் மற்றும் வெளிநாட்டவர் அனைவருக்கும் பாதுகாப்பு அளிக்கிறது.","difficulty":"medium","topic":"அடிப்படை உரிமைகள்"},{"id":331,"subject":"gk","testNumber":4,"question":"எந்தவொரு நபரும் தனது மனசாட்சிப்படி எந்த மதத்தையும் ஏற்கவும், பின்பற்றவும் மற்றும் பரப்பவும் உரிமை வழங்கும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 28","சட்டப்பிரிவு 27","சட்டப்பிரிவு 25","சட்டப்பிரிவு 26"],"correctAnswer":2,"explanation":"சமயச் சுதந்திர உரிமையின் கீழ் வரும் சட்டப்பிரிவு 25 அனைவருக்கும் மனசாட்சிச் சுதந்திரத்தையும், எந்தவொரு மதத்தையும் சுதந்திரமாக ஏற்கவும், பின்பற்றவும், பரப்பவும் உரிமையை வழங்குகிறது. இவ்வுரிமை பொது அமைதி, ஒழுக்கம் மற்றும் சுகாதாரத்திற்கு உட்பட்டதாகும்.","difficulty":"medium","topic":"அடிப்படை உரிமைகள்"},{"id":332,"subject":"gk","testNumber":4,"question":"மத மற்றும் மொழிவாரிச் சிறுபான்மையினர் தங்கள் விருப்பப்படி கல்வி நிறுவனங்களை நிறுவி நிர்வகிப்பதற்கான உரிமையை வழங்கும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 28","சட்டப்பிரிவு 30","சட்டப்பிரிவு 27","சட்டப்பிரிவு 29"],"correctAnswer":1,"explanation":"பண்பாடு மற்றும் கல்வி உரிமையின் கீழ் வரும் சட்டப்பிரிவு 30 மத மற்றும் மொழிவாரிச் சிறுபான்மையினர் தாங்கள் விரும்பும் கல்வி நிறுவனங்களை நிறுவி நிர்வகிக்கும் உரிமையை வழங்குகிறது. சட்டப்பிரிவு 29 சிறுபான்மையினரின் மொழி, எழுத்து மற்றும் பண்பாட்டைப் பாதுகாக்கிறது.","difficulty":"medium","topic":"அடிப்படை உரிமைகள்"},{"id":333,"subject":"gk","testNumber":4,"question":"அரசியலமைப்புக்குட்பட்டு தீர்வு காணும் உரிமையான சட்டப்பிரிவு 32-ஐ 'இந்திய அரசியலமைப்பின் இதயம் மற்றும் ஆன்மா' என்று வர்ணித்தவர் யார்?","options":["டாக்டர் ராஜேந்திர பிரசாத்","ஜவஹர்லால் நேரு","டாக்டர் பி.ஆர். அம்பேத்கர்","சர்தார் வல்லபாய் படேல்"],"correctAnswer":2,"explanation":"குடிமக்களின் அடிப்படை உரிமைகள் மீறப்படும்போது நேரடியாக உச்ச நீதிமன்றத்தை அணுகி நீதிப்பேராணைகள் மூலம் தீர்வு காண வழிவகுக்கும் சட்டப்பிரிவு 32-ஐ டாக்டர் பி.ஆர். அம்பேத்கர் 'அரசியலமைப்பின் இதயம் மற்றும் ஆன்மா' என்று குறிப்பிட்டார்.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":334,"subject":"gk","testNumber":4,"question":"சட்டவிரோதமாகக் கைது செய்யப்பட்டுத் தடுத்து வைக்கப்பட்டுள்ள ஒரு நபரை நீதிமன்றத்தின் முன் ஆஜர்படுத்துமாறு உத்தரவிடும் நீதிப்பேராணை எது?","options":["தடையுறுத்தும் நீதிப்பேராணை (Prohibition)","தகுதி வினவும் நீதிப்பேராணை (Quo Warranto)","ஆட்கொணர்வு நீதிப்பேராணை (Habeas Corpus)","கட்டளையுறுத்தும் நீதிப்பேராணை (Mandamus)"],"correctAnswer":2,"explanation":"ஆட்கொணர்வு நீதிப்பேராணை (Habeas Corpus) என்பது 'உடலை முன்னிலைப்படுத்துக' என்ற பொருளைக் கொண்டது. சட்டவிரோதமாகக் கைது செய்யப்பட்ட அல்லது தடுத்து வைக்கப்பட்ட நபரின் தனிப்பட்ட சுதந்திரத்தைப் பாதுகாக்க நீதிமன்றம் இதைப் பிறப்பிக்கிறது.","difficulty":"easy","topic":"அடிப்படை உரிமைகள்"},{"id":335,"subject":"gk","testNumber":4,"question":"அரசுப் பணியாளர் அல்லது பொது அமைப்பு தனது சட்டப்பூர்வக் கடமையைச் செய்யத் தவறும்போது, அக்கடமையைச் செய்யுமாறு நீதிமன்றம் பிறப்பிக்கும் நீதிப்பேராணை எது?","options":["தகுதி வினவும் நீதிப்பேராணை (Quo Warranto)","கட்டளையுறுத்தும் நீதிப்பேராணை (Mandamus)","ஆட்கொணர்வு நீதிப்பேராணை (Habeas Corpus)","ஆவணக் கேட்பு நீதிப்பேராணை (Certiorari)"],"correctAnswer":1,"explanation":"கட்டளையுறுத்தும் நீதிப்பேராணை (Mandamus) என்பது 'நாம் கட்டளையிடுகிறோம்' என்ற பொருளை உடையது. பொது அலுவலர் அல்லது அரசு நிறுவனம் தனது சட்டப்பூர்வக் கடமையை நிறைவேற்றத் தவறும்போது அதனைச் செய்யுமாறு நீதிமன்றம் இக்கட்டளையைப் பிறப்பிக்கிறது.","difficulty":"medium","topic":"அடிப்படை உரிமைகள்"},{"id":336,"subject":"gk","testNumber":4,"question":"சட்டவிரோதமாக ஒரு பொதுப் பதவியை வகிக்கும் நபரிடம் 'எந்த அதிகாரத்தின் அடிப்படையில் இப்பதவியில் உள்ளீர்?' எனக் கேள்வி எழுப்பும் நீதிப்பேராணை எது?","options":["ஆவணக் கேட்பு நீதிப்பேராணை (Certiorari)","தகுதி வினவும் நீதிப்பேராணை (Quo Warranto)","தடையுறுத்தும் நீதிப்பேராணை (Prohibition)","கட்டளையுறுத்தும் நீதிப்பேராணை (Mandamus)"],"correctAnswer":1,"explanation":"தகுதி வினவும் நீதிப்பேராணை (Quo Warranto) என்பது 'எந்த அதிகாரத்தால்?' எனப் பொருள்படும். தகுதியற்ற நபர் ஒரு பொதுப் பதவியைச் சட்டவிரோதமாகக் கைப்பற்றுவதைத் தடுக்கவும், அவரின் பதவி வகிக்கும் உரிமையை விசாரிக்கவும் நீதிமன்றம் இதைப் பிறப்பிக்கிறது.","difficulty":"hard","topic":"அடிப்படை உரிமைகள்"},{"id":337,"subject":"gk","testNumber":4,"question":"கீழ் நீதிமன்றம் தனது அதிகார வரம்பை மீறி வழங்கிய தீர்ப்பை ரத்து செய்ய அல்லது நிலுவையில் உள்ள வழக்கின் ஆவணங்களை மேல் நீதிமன்றத்திற்கு மாற்றப் பிறப்பிக்கப்படும் நீதிப்பேராணை எது?","options":["ஆட்கொணர்வு நீதிப்பேராணை (Habeas Corpus)","ஆவணக் கேட்பு நீதிப்பேராணை (Certiorari)","கட்டளையுறுத்தும் நீதிப்பேராணை (Mandamus)","தகுதி வினவும் நீதிப்பேராணை (Quo Warranto)"],"correctAnswer":1,"explanation":"ஆவணக் கேட்பு நீதிப்பேராணை (Certiorari) என்பது கீழ் நீதிமன்றம் அல்லது தீர்ப்பாயம் தனது அதிகார வரம்பை மீறி வழங்கிய உத்தரவை ரத்து செய்யவோ, வழக்கை மேல் நீதிமன்றத்திற்கு மாற்றவோ பிறப்பிக்கப்படுகிறது. இதேபோல் கீழ் நீதிமன்றம் அதிகார வரம்பை மீறி செயல்படுவதை முன்கூட்டியே தடுக்க 'தடையுறுத்தும் நீதிப்பேராணை' (Prohibition) பிறப்பிக்கப்படுகிறது.","difficulty":"hard","topic":"அடிப்படை உரிமைகள்"},{"id":338,"subject":"gk","testNumber":4,"question":"சொத்துரிமை (Right to Property) எந்த அரசியலமைப்புச் சட்டத்திருத்தத்தின் மூலம் அடிப்படை உரிமையிலிருந்து நீக்கப்பட்டு சட்ட உரிமையாக்கப்பட்டது?","options":["61-ஆவது சட்டத்திருத்தம் (1988)","44-ஆவது சட்டத்திருத்தம் (1978)","42-ஆவது சட்டத்திருத்தம் (1976)","52-ஆவது சட்டத்திருத்தம் (1985)"],"correctAnswer":1,"explanation":"1978-ஆம் ஆண்டு 44-ஆவது அரசியலமைப்புச் சட்டத்திருத்தத்தின் மூலம் சொத்துரிமை (முன்பு பிரிவு 31) அடிப்படை உரிமைகள் பட்டியலிலிருந்து நீக்கப்பட்டது. தற்போது இது பகுதி XII-இல் சட்டப்பிரிவு 300A-இன் கீழ் ஒரு சட்ட உரிமையாக வைக்கப்பட்டுள்ளது.","difficulty":"medium","topic":"அடிப்படை உரிமைகள்"},{"id":339,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பின் பகுதி IV-இல் (சட்டப்பிரிவுகள் 36–51) இடம்பெற்றுள்ள 'அரசு நெறிமுறைக் கோட்பாடுகள்' (DPSP) எந்த நாட்டு அரசியலமைப்பிலிருந்து பெறப்பட்டன?","options":["கனடா","அமெரிக்க ஐக்கிய நாடுகள்","அயர்லாந்து","இங்கிலாந்து"],"correctAnswer":2,"explanation":"அரசு நெறிமுறைக் கோட்பாடுகள் (Directive Principles of State Policy) அயர்லாந்து நாட்டு அரசியலமைப்பிலிருந்து பெறப்பட்டன. இவை ஒரு மக்கள் நல அரசை (Welfare State) உருவாக்குவதற்கான வழிகாட்டுதல்களை அரசுக்கு வழங்குகின்றன; ஆனால் நீதிமன்றத்தால் கட்டாயப்படுத்த இயலாதவை.","difficulty":"easy","topic":"அரசு நெறிமுறைக் கோட்பாடுகள்"},{"id":340,"subject":"gk","testNumber":4,"question":"கிராமப் பஞ்சாயத்துகளை அமைத்து அவை தன்னாட்சி அலகுகளாகச் செயல்படத் தேவையான அதிகாரங்களை வழங்க வேண்டும் எனக் கூறும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 42","சட்டப்பிரிவு 39","சட்டப்பிரிவு 40","சட்டப்பிரிவு 38"],"correctAnswer":2,"explanation":"காந்தியக் கோட்பாடுகளின் கீழ் வரும் சட்டப்பிரிவு 40 கிராமப் பஞ்சாயத்துகளை அமைக்க அரசு நடவடிக்கை எடுக்க வேண்டும் என வலியுறுத்துகிறது. இதன் அடிப்படையிலேயே பின்னர் 73-ஆவது சட்டத்திருத்தம் மூலம் பஞ்சாயத்து ராஜ் அமைப்புகளுக்கு அரசியலமைப்பு அந்தஸ்து வழங்கப்பட்டது.","difficulty":"medium","topic":"அரசு நெறிமுறைக் கோட்பாடுகள்"},{"id":341,"subject":"gk","testNumber":4,"question":"இந்திய நாடு முழுவதும் உள்ள குடிமக்களுக்கு 'ஒரே மாதிரியான சிவில் சட்டம்' (Uniform Civil Code) உருவாக்க அரசு முயற்சிக்க வேண்டும் எனக் கூறும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 43","சட்டப்பிரிவு 48","சட்டப்பிரிவு 45","சட்டப்பிரிவு 44"],"correctAnswer":3,"explanation":"தாராளவாத-அறிவுசார் கோட்பாடுகளின் கீழ் வரும் சட்டப்பிரிவு 44 இந்திய எல்லை முழுவதும் உள்ள குடிமக்களுக்குப் பொதுவான சிவில் சட்டத்தை (Uniform Civil Code) உறுதி செய்ய அரசு பாடுபட வேண்டும் எனக் கூறுகிறது.","difficulty":"medium","topic":"அரசு நெறிமுறைக் கோட்பாடுகள்"},{"id":342,"subject":"gk","testNumber":4,"question":"அரசின் பொதுப் பணிகளில் நீதித்துறையை நிர்வாகத்துறையிலிருந்து பிரிக்க வேண்டும் என அறிவுறுத்தும் அரசு நெறிமுறைக் கோட்பாடு சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 50","சட்டப்பிரிவு 49","சட்டப்பிரிவு 47","சட்டப்பிரிவு 48A"],"correctAnswer":0,"explanation":"சட்டப்பிரிவு 50 அரசின் பொதுப் பணிகளில் நீதித்துறையை நிர்வாகத்துறையிலிருந்து பிரிப்பதற்கான நடவடிக்கைகளை அரசு மேற்கொள்ள வேண்டும் எனக் கூறுகிறது. இது சுதந்திரமான நீதித்துறையை உறுதி செய்ய உதவுகிறது.","difficulty":"hard","topic":"அரசு நெறிமுறைக் கோட்பாடுகள்"},{"id":343,"subject":"gk","testNumber":4,"question":"சர்வதேச அமைதி மற்றும் பாதுகாப்பை மேம்படுத்துதல், நாடுகளுக்கிடையே நியாயமான உறவுகளைப் பேணுதல் ஆகியவற்றைக் கூறும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 51","சட்டப்பிரிவு 49","சட்டப்பிரிவு 50","சட்டப்பிரிவு 46"],"correctAnswer":0,"explanation":"அரசு நெறிமுறைக் கோட்பாடுகளின் இறுதிப் பிரிவான சட்டப்பிரிவு 51 சர்வதேச அமைதி மற்றும் பாதுகாப்பை மேம்படுத்தவும், சர்வதேசச் சட்டங்கள் மற்றும் ஒப்பந்தங்களுக்கு மதிப்பளிக்கவும், நாடுகளுக்கிடையேயான சிக்கல்களை நடுவர் தீர்வு மூலம் தீர்க்கவும் வலியுறுத்துகிறது.","difficulty":"hard","topic":"அரசு நெறிமுறைக் கோட்பாடுகள்"},{"id":344,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பில் அடிப்படைக் கடமைகள் (பகுதி IVA, சட்டப்பிரிவு 51A) எந்தக் குழுவின் பரிந்துரையின் அடிப்படையில் சேர்க்கப்பட்டன?","options":["பல்வந்த்ராய் மேத்தா குழு","ஸ்வரன் சிங் குழு","ராஜமன்னார் குழு","சர்க்காரியா குழு"],"correctAnswer":1,"explanation":"சர்தார் ஸ்வரன் சிங் குழுவின் பரிந்துரையின் அடிப்படையில் 1976-ஆம் ஆண்டு 42-ஆவது சட்டத்திருத்தத்தின் மூலம் பகுதி IVA மற்றும் சட்டப்பிரிவு 51A சேர்க்கப்பட்டன. அடிப்படைக் கடமைகள் சோவியத் ரஷ்யா (USSR) அரசியலமைப்பிலிருந்து பெறப்பட்டன.","difficulty":"easy","topic":"அடிப்படைக் கடமைகள்"},{"id":345,"subject":"gk","testNumber":4,"question":"6 முதல் 14 வயதுக்குட்பட்ட குழந்தைகளுக்குக் கல்வி கற்பதற்கான வாய்ப்புகளை வழங்குவது பெற்றோர் அல்லது பாதுகாவலரின் கடமை என்ற 11-ஆவது அடிப்படைக் கடமை எந்தச் சட்டத்திருத்தத்தால் சேர்க்கப்பட்டது?","options":["44-ஆவது சட்டத்திருத்தம் (1978)","42-ஆவது சட்டத்திருத்தம் (1976)","86-ஆவது சட்டத்திருத்தம் (2002)","74-ஆவது சட்டத்திருத்தம் (1992)"],"correctAnswer":2,"explanation":"1976-இல் 42-ஆவது சட்டத்திருத்தத்தின் மூலம் தொடக்கத்தில் 10 அடிப்படைக் கடமைகள் சேர்க்கப்பட்டன. பின்னர் 2002-ஆம் ஆண்டு 86-ஆவது சட்டத்திருத்தத்தின் மூலம் பிரிவு 51A(k)-ஆக 11-ஆவது அடிப்படைக் கடமை சேர்க்கப்பட்டது.","difficulty":"medium","topic":"அடிப்படைக் கடமைகள்"},{"id":346,"subject":"gk","testNumber":4,"question":"இந்தியக் குடியரசுத் தலைவர் தேர்தலில் போட்டியிடத் தேவையான குறைந்தபட்ச வயது மற்றும் அவரது பதவிக்காலம் முறையே என்ன?","options":["35 வயது மற்றும் 6 ஆண்டுகள்","25 வயது மற்றும் 5 ஆண்டுகள்","30 வயது மற்றும் 6 ஆண்டுகள்","35 வயது மற்றும் 5 ஆண்டுகள்"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 58-இன்படி இந்தியக் குடியரசுத் தலைவர் பதவிக்குப் போட்டியிடுபவர் இந்தியக் குடிமகனாகவும், 35 வயது பூர்த்தி அடைந்தவராகவும், மக்களவை உறுப்பினராவதற்கான தகுதி பெற்றவராகவும் இருக்க வேண்டும். அவரது பதவிக்காலம் 5 ஆண்டுகள் ஆகும்.","difficulty":"easy","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":347,"subject":"gk","testNumber":4,"question":"இந்தியக் குடியரசுத் தலைவரைத் தேர்ந்தெடுக்கும் வாக்காளர் குழுமத்தில் (Electoral College) கீழ்க்கண்டவர்களில் யார் பங்கேற்க முடியாது?","options":["மக்களவையின் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள்","நாடாளுமன்றம் மற்றும் மாநில சட்டமன்றங்களின் நியமன உறுப்பினர்கள்","மாநில சட்டமன்றப் பேரவைகளின் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள்","டெல்லி மற்றும் புதுச்சேரி சட்டமன்றங்களின் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள்"],"correctAnswer":1,"explanation":"குடியரசுத் தலைவர் தேர்தல் வாக்காளர் குழுமத்தில் நாடாளுமன்றத்தின் இரு அவைகளின் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள், அனைத்து மாநில சட்டமன்றப் பேரவைகள் மற்றும் டெல்லி, புதுச்சேரி சட்டமன்றங்களின் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள் மட்டுமே இடம்பெறுவர். நியமன உறுப்பினர்களும் மாநில சட்டமேலவை உறுப்பினர்களும் இதில் வாக்களிக்க முடியாது.","difficulty":"hard","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":348,"subject":"gk","testNumber":4,"question":"அரசியலமைப்பை மீறியதாகக் குற்றம் சாட்டி குடியரசுத் தலைவரைப் பதவி நீக்கம் செய்யும் (Impeachment) நடைமுறை எந்தச் சட்டப்பிரிவில் கூறப்பட்டுள்ளது?","options":["சட்டப்பிரிவு 60","சட்டப்பிரிவு 61","சட்டப்பிரிவு 52","சட்டப்பிரிவு 56"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 61 குடியரசுத் தலைவரைப் பதவி நீக்கம் செய்யும் நடைமுறையை விவரிக்கிறது. இதற்கான தீர்மானத்தை நாடாளுமன்றத்தின் எந்த அவையிலும் கொண்டு வரலாம்; ஆனால் 14 நாட்கள் முன்னறிவிப்பு மற்றும் இரு அவைகளிலும் மொத்த உறுப்பினர்களில் மூன்றில் இரண்டு பங்கு பெரும்பான்மை தேவை.","difficulty":"medium","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":349,"subject":"gk","testNumber":4,"question":"மரண தண்டனை உட்பட நீதிமன்றத் தண்டனைகளை மன்னிக்கவும், குறைக்கவும் அல்லது ஒத்திவைக்கவும் குடியரசுத் தலைவருக்கு அதிகாரம் அளிக்கும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 123","சட்டப்பிரிவு 72","சட்டப்பிரிவு 74","சட்டப்பிரிவு 161"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 72 குடியரசுத் தலைவருக்கு மன்னிப்பு வழங்கும் (Pardoning Power) அதிகாரத்தை அளிக்கிறது. இராணுவ நீதிமன்றத் தண்டனை மற்றும் மரண தண்டனை ஆகியவற்றை முழுமையாக மன்னிக்கும் அதிகாரம் குடியரசுத் தலைவருக்கு மட்டுமே உள்ளது.","difficulty":"medium","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":350,"subject":"gk","testNumber":4,"question":"நாடாளுமன்றம் கூட்டத்தொடரில் இல்லாதபோது குடியரசுத் தலைவர் அவசரச் சட்டம் (Ordinance) பிறப்பிக்க அதிகாரம் அளிக்கும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 110","சட்டப்பிரிவு 143","சட்டப்பிரிவு 123","சட்டப்பிரிவு 213"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 123-இன்படி நாடாளுமன்றத்தின் இரு அவைகளோ அல்லது ஏதேனும் ஒரு அவையோ கூட்டத்தொடரில் இல்லாதபோது உடனடித் தேவைக்காகக் குடியரசுத் தலைவர் அவசரச் சட்டம் பிறப்பிக்கலாம். நாடாளுமன்றம் மீண்டும் கூடிய 6 வாரங்களுக்குள் அதற்கு ஒப்புதல் பெற வேண்டும்.","difficulty":"medium","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":351,"subject":"gk","testNumber":4,"question":"போர், வெளிநாட்டு ஆக்கிரமிப்பு அல்லது ஆயுதக் கிளர்ச்சி காரணமாக இந்தியாவில் தேசிய அவசரநிலை (National Emergency) எந்தச் சட்டப்பிரிவின் கீழ் அறிவிக்கப்படுகிறது?","options":["சட்டப்பிரிவு 356","சட்டப்பிரிவு 365","சட்டப்பிரிவு 352","சட்டப்பிரிவு 360"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 352-இன் கீழ் போர், வெளிநாட்டு ஆக்கிரமிப்பு அல்லது ஆயுதக் கிளர்ச்சி ஆகிய காரணங்களுக்காகக் குடியரசுத் தலைவர் தேசிய அவசரநிலையை அறிவிக்கலாம். இந்தியாவில் இதுவரை 1962, 1971 மற்றும் 1975 ஆகிய மூன்று முறை தேசிய அவசரநிலை அறிவிக்கப்பட்டுள்ளது.","difficulty":"easy","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":352,"subject":"gk","testNumber":4,"question":"ஒரு மாநிலத்தில் அரசியலமைப்பு விதிகளின்படி ஆட்சி நடைபெற இயலாத சூழலில் குடியரசுத் தலைவர் ஆட்சி (மாநில அவசரநிலை) எந்தச் சட்டப்பிரிவின் கீழ் அமல்படுத்தப்படுகிறது?","options":["சட்டப்பிரிவு 360","சட்டப்பிரிவு 352","சட்டப்பிரிவு 356","சட்டப்பிரிவு 358"],"correctAnswer":2,"explanation":"மாநில ஆளுநரின் அறிக்கையின் அடிப்படையிலோ அல்லது வேறு வகையிலோ ஒரு மாநில அரசு அரசியலமைப்பு விதிகளுக்கு ஏற்ப செயல்பட இயலவில்லை எனக் குடியரசுத் தலைவர் கருதினால், சட்டப்பிரிவு 356-இன் கீழ் அம்மாநிலத்தில் குடியரசுத் தலைவர் ஆட்சியைப் பிறப்பிக்கலாம்.","difficulty":"easy","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":353,"subject":"gk","testNumber":4,"question":"நிதி நெருக்கடி நிலை (Financial Emergency) எந்தச் சட்டப்பிரிவில் கூறப்பட்டுள்ளது மற்றும் இதுவரை இந்தியாவில் எத்தனை முறை அறிவிக்கப்பட்டுள்ளது?","options":["சட்டப்பிரிவு 356; மூன்று முறை அறிவிக்கப்பட்டது","சட்டப்பிரிவு 360; இதுவரை ஒருமுறை கூட அறிவிக்கப்படவில்லை","சட்டப்பிரிவு 360; 1991-இல் ஒருமுறை அறிவிக்கப்பட்டது","சட்டப்பிரிவு 352; இருமுறை அறிவிக்கப்பட்டது"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 360-இன் கீழ் இந்தியாவின் நிதி நிலைத்தன்மை அல்லது கடன் நம்பகத்தன்மைக்கு அச்சுறுத்தல் ஏற்படும்போது குடியரசுத் தலைவர் நிதி நெருக்கடி நிலையை அறிவிக்கலாம். ஆனால் சுதந்திர இந்தியாவில் இதுவரை ஒருமுறை கூட நிதி நெருக்கடி நிலை அறிவிக்கப்படவில்லை.","difficulty":"medium","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":354,"subject":"gk","testNumber":4,"question":"இந்தியாவின் துணைக் குடியரசுத் தலைவர் எதன் பதவி வழித் தலைவராக (Ex-officio Chairman) செயல்படுகிறார்?","options":["தேசிய வளர்ச்சி மன்றம்","நிதி ஆயோக்","மக்களவை","மாநிலங்களவை"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 64-இன்படி இந்தியாவின் துணைக் குடியரசுத் தலைவர் மாநிலங்களவையின் (Rajya Sabha) பதவி வழித் தலைவராகச் செயல்படுகிறார். ஆனால் இவர் மாநிலங்களவையின் உறுப்பினர் அல்ல; சம வாக்குகள் ஏற்படும்போது மட்டுமே வாக்களிக்கும் (Casting Vote) உரிமை இவருக்கு உண்டு.","difficulty":"easy","topic":"குடியரசுத் தலைவர் & துணைக் குடியரசுத் தலைவர்"},{"id":355,"subject":"gk","testNumber":4,"question":"சட்டப்பிரிவு 75(3)-இன்படி பிரதமர் தலைமையிலான மத்திய அமைச்சரவை கூட்டுப் பொறுப்புடன் (Collective Responsibility) யாருக்குப் பொறுப்புடையதாக உள்ளது?","options":["மாநிலங்களவைக்கு","உச்ச நீதிமன்றத்திற்கு","குடியரசுத் தலைவருக்கு","மக்களவைக்கு"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 75(3)-இன்படி மத்திய அமைச்சரவை கூட்டுப் பொறுப்புடன் மக்களவைக்குப் (Lok Sabha) பொறுப்புடையதாகும். மக்களவையில் நம்பிக்கையில்லாத் தீர்மானம் நிறைவேற்றப்பட்டால் பிரதமர் உட்பட ஒட்டுமொத்த அமைச்சரவையும் பதவி விலக வேண்டும்.","difficulty":"medium","topic":"பிரதமர் & அமைச்சரவை"},{"id":356,"subject":"gk","testNumber":4,"question":"மத்திய அமைச்சரவையின் நிர்வாக மற்றும் சட்டமியற்றும் முடிவுகளைக் குடியரசுத் தலைவருக்குத் தெரிவிப்பது பிரதமரின் கடமை என்று கூறும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 75","சட்டப்பிரிவு 80","சட்டப்பிரிவு 74","சட்டப்பிரிவு 78"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 78 குடியரசுத் தலைவருக்குத் தகவல்களை வழங்குவதில் பிரதமரின் கடமைகளைக் குறிப்பிடுகிறது. இதன் மூலம் பிரதமர் குடியரசுத் தலைவருக்கும் மத்திய அமைச்சரவைக்கும் இடையே முக்கியத் தொடர்புப் பாலமாகச் செயல்படுகிறார்.","difficulty":"hard","topic":"பிரதமர் & அமைச்சரவை"},{"id":357,"subject":"gk","testNumber":4,"question":"2003-ஆம் ஆண்டு 91-ஆவது அரசியலமைப்புச் சட்டத்திருத்தத்தின்படி, பிரதமர் உட்பட மத்திய அமைச்சர்களின் மொத்த எண்ணிக்கை மக்களவையின் மொத்த உறுப்பினர் எண்ணிக்கையில் எத்தனை சதவீதத்திற்கு மிகாமல் இருக்க வேண்டும்?","options":["12 சதவீதம்","20 சதவீதம்","10 சதவீதம்","15 சதவீதம்"],"correctAnswer":3,"explanation":"91-ஆவது அரசியலமைப்புச் சட்டத்திருத்தம் (2003) சட்டப்பிரிவு 75(1A)-ஐச் சேர்த்தது. இதன்படி பிரதமர் உட்பட மத்திய அமைச்சர்களின் எண்ணிக்கை மக்களவையின் மொத்த உறுப்பினர்களில் 15 சதவீதத்திற்கு மிகாமல் இருக்க வேண்டும்.","difficulty":"hard","topic":"பிரதமர் & அமைச்சரவை"},{"id":358,"subject":"gk","testNumber":4,"question":"சட்டப்பிரிவு 79-இன்படி இந்திய நாடாளுமன்றம் எவற்றை உள்ளடக்கியதாகும்?","options":["குடியரசுத் தலைவர், துணைக் குடியரசுத் தலைவர் மற்றும் பிரதமர்","மாநிலங்களவை மற்றும் மக்களவை மட்டுமே","குடியரசுத் தலைவர், மாநிலங்களவை மற்றும் மக்களவை","பிரதமர், மாநிலங்களவை மற்றும் மக்களவை"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 79-இன்படி இந்திய நாடாளுமன்றம் என்பது குடியரசுத் தலைவர், மாநிலங்களவை (மேலவை) மற்றும் மக்களவை (கீழவை) ஆகிய மூன்றையும் உள்ளடக்கியதாகும். நாடாளுமன்றத்தின் இரு அவைகளிலும் நிறைவேற்றப்படும் மசோதா குடியரசுத் தலைவரின் ஒப்புதல் பெற்ற பின்னரே சட்டமாகிறது.","difficulty":"easy","topic":"நாடாளுமன்றம்"},{"id":359,"subject":"gk","testNumber":4,"question":"நிரந்தர அவையான மாநிலங்களவை (Rajya Sabha) உறுப்பினர்களின் பதவிக்காலம் எத்தனை ஆண்டுகள் மற்றும் எத்தனை ஆண்டுகளுக்கு ஒருமுறை மூன்றில் ஒரு பங்கு உறுப்பினர்கள் ஓய்வு பெறுவர்?","options":["6 ஆண்டுகள்; 3 ஆண்டுகளுக்கு ஒருமுறை","5 ஆண்டுகள்; 2 ஆண்டுகளுக்கு ஒருமுறை","5 ஆண்டுகள்; ஒவ்வொரு ஆண்டும்","6 ஆண்டுகள்; 2 ஆண்டுகளுக்கு ஒருமுறை"],"correctAnswer":3,"explanation":"மாநிலங்களவை ஒரு நிரந்தர அவை என்பதால் இதனைக் கலைக்க முடியாது. இதன் உறுப்பினர்களின் பதவிக்காலம் 6 ஆண்டுகள் ஆகும்; மேலும் ஒவ்வொரு 2 ஆண்டுகளுக்கும் ஒருமுறை மூன்றில் ஒரு பங்கு உறுப்பினர்கள் ஓய்வு பெற்று புதிய உறுப்பினர்கள் தேர்ந்தெடுக்கப்படுவர்.","difficulty":"easy","topic":"நாடாளுமன்றம்"},{"id":360,"subject":"gk","testNumber":4,"question":"இலக்கியம், அறிவியல், கலை மற்றும் சமூக சேவை ஆகிய துறைகளில் சிறந்து விளங்கும் எத்தனை உறுப்பினர்களைக் குடியரசுத் தலைவர் மாநிலங்களவைக்கு நியமனம் செய்கிறார்?","options":["10 உறுப்பினர்கள்","2 உறுப்பினர்கள்","14 உறுப்பினர்கள்","12 உறுப்பினர்கள்"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 80-இன்படி இலக்கியம், அறிவியல், கலை மற்றும் சமூக சேவை ஆகிய துறைகளில் சிறப்பு அறிவும் அனுபவமும் பெற்ற 12 உறுப்பினர்களைக் குடியரசுத் தலைவர் மாநிலங்களவைக்கு நியமனம் செய்கிறார். மாநிலங்களவையின் அதிகபட்ச உறுப்பினர் எண்ணிக்கை 250 ஆகும்.","difficulty":"easy","topic":"நாடாளுமன்றம்"},{"id":361,"subject":"gk","testNumber":4,"question":"மக்களவைத் தேர்தலில் போட்டியிடத் தேவையான குறைந்தபட்ச வயது என்ன மற்றும் தமிழ்நாட்டிலிருந்து நாடாளுமன்றத்தின் மக்களவை மற்றும் மாநிலங்களவைக்குத் தேர்ந்தெடுக்கப்படும் உறுப்பினர்கள் எண்ணிக்கை முறையே எத்தனை?","options":["21 வயது; 39 மற்றும் 16","30 வயது; 40 மற்றும் 18","25 வயது; 39 மற்றும் 18","25 வயது; 38 மற்றும் 20"],"correctAnswer":2,"explanation":"மக்களவை உறுப்பினராகப் போட்டியிடக் குறைந்தபட்ச வயது 25 ஆண்டுகள் ஆகும் (மாநிலங்களவைக்கு 30 வயது). தமிழ்நாட்டிலிருந்து மக்களவைக்கு 39 உறுப்பினர்களும், மாநிலங்களவைக்கு 18 உறுப்பினர்களும் தேர்ந்தெடுக்கப்படுகின்றனர்.","difficulty":"medium","topic":"நாடாளுமன்றம்"},{"id":362,"subject":"gk","testNumber":4,"question":"பண மசோதா (Money Bill) குறித்த வரையறை எந்தச் சட்டப்பிரிவில் உள்ளது மற்றும் ஒரு மசோதா பண மசோதாவா இல்லையா என்பதை இறுதியாகத் தீர்மானிப்பவர் யார்?","options":["சட்டப்பிரிவு 112; மத்திய நிதியமைச்சர்","சட்டப்பிரிவு 110; மாநிலங்களவைத் தலைவர்","சட்டப்பிரிவு 110; மக்களவை சபாநாயகர்","சட்டப்பிரிவு 108; குடியரசுத் தலைவர்"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 110 பண மசோதாவை வரையறுக்கிறது. ஒரு மசோதா பண மசோதாவா இல்லையா என்பதைத் தீர்மானிக்கும் இறுதி அதிகாரம் மக்களவை சபாநாயகருக்கு மட்டுமே உள்ளது; பண மசோதாவை மக்களவையில் மட்டுமே அறிமுகப்படுத்த முடியும்.","difficulty":"medium","topic":"நாடாளுமன்றம்"},{"id":363,"subject":"gk","testNumber":4,"question":"மக்களவையில் நிறைவேற்றப்பட்டு அனுப்பப்பட்ட பண மசோதாவை மாநிலங்களவை அதிகபட்சமாக எத்தனை நாட்கள் மட்டுமே தன் பரிசீலனையில் வைத்திருக்க முடியும்?","options":["30 நாட்கள்","21 நாட்கள்","14 நாட்கள்","6 மாதங்கள்"],"correctAnswer":2,"explanation":"பண மசோதாவை மாநிலங்களவை திருத்தவோ அல்லது நிராகரிக்கவோ முடியாது. மக்களவை அனுப்பிய 14 நாட்களுக்குள் மாநிலங்களவை தனது பரிந்துரைகளுடன் திருப்பி அனுப்ப வேண்டும்; இல்லையெனில் 14 நாட்களுக்குப் பிறகு இரு அவைகளிலும் நிறைவேற்றப்பட்டதாகக் கருதப்படும்.","difficulty":"medium","topic":"நாடாளுமன்றம்"},{"id":364,"subject":"gk","testNumber":4,"question":"சாதாரண மசோதா தொடர்பாக இரு அவைகளுக்கும் இடையே கருத்து வேறுபாடு ஏற்படும்போது சட்டப்பிரிவு 108-இன் கீழ் கூட்டுக் கூட்டத்தை (Joint Sitting) அழைப்பவர் மற்றும் அதற்குத் தலைமை தாங்குபவர் முறையே யார்?","options":["குடியரசுத் தலைவர் அழைப்பார்; துணைக் குடியரசுத் தலைவர் தலைமை தாங்குவார்","குடியரசுத் தலைவர் அழைப்பார்; மக்களவை சபாநாயகர் தலைமை தாங்குவார்","பிரதமர் அழைப்பார்; துணைக் குடியரசுத் தலைவர் தலைமை தாங்குவார்","சபாநாயகர் அழைப்பார்; குடியரசுத் தலைவர் தலைமை தாங்குவார்"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 108-இன் கீழ் நாடாளுமன்றத்தின் இரு அவைகளின் கூட்டுக் கூட்டத்தைக் குடியரசுத் தலைவர் அழைப்பார். சட்டப்பிரிவு 118(4)-இன்படி அக்கூட்டுக் கூட்டத்திற்கு மக்களவை சபாநாயகர் தலைமை தாங்குவார்; அவர் இல்லாதபோது துணை சபாநாயகர் தலைமை தாங்குவார்.","difficulty":"medium","topic":"நாடாளுமன்றம்"},{"id":365,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பின் சட்டப்பிரிவு 85-இன்படி நாடாளுமன்றத்தின் இரு கூட்டத்தொடர்களுக்கு இடையே இருக்கக்கூடிய அதிகபட்ச கால இடைவெளி எவ்வளவு?","options":["3 மாதங்கள்","1 ஆண்டு","6 மாதங்கள்","4 மாதங்கள்"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 85-இன்படி நாடாளுமன்றத்தின் ஒரு கூட்டத்தொடரின் இறுதி அமர்விற்கும் அடுத்த கூட்டத்தொடரின் முதல் அமர்விற்கும் இடையே 6 மாதங்களுக்கு மேல் இடைவெளி இருக்கக் கூடாது. அதாவது நாடாளுமன்றம் ஆண்டுக்குக் குறைந்தது இரண்டு முறையாவது கூட வேண்டும்.","difficulty":"easy","topic":"நாடாளுமன்றம்"},{"id":366,"subject":"gk","testNumber":4,"question":"இந்திய உச்ச நீதிமன்றம் அமைப்பதற்கான அரசியலமைப்புச் சட்டப்பிரிவு எது மற்றும் உச்ச நீதிமன்றம் எப்போது தொடங்கி வைக்கப்பட்டது?","options":["சட்டப்பிரிவு 131; 1947 ஆகஸ்ட் 15","சட்டப்பிரிவு 124; 1950 ஜனவரி 26","சட்டப்பிரிவு 124; 1950 ஜனவரி 28","சட்டப்பிரிவு 214; 1950 ஜனவரி 28"],"correctAnswer":2,"explanation":"இந்திய அரசியலமைப்பின் பகுதி V-இல் உள்ள சட்டப்பிரிவு 124 உச்ச நீதிமன்றம் அமைப்பதைப் பற்றிக் கூறுகிறது. இந்திய உச்ச நீதிமன்றம் 1950 ஜனவரி 28-ஆம் நாள் புதுடெல்லியில் தொடங்கி வைக்கப்பட்டது; இதன் முதல் தலைமை நீதிபதி ஹெச்.ஜே. கனியா ஆவார்.","difficulty":"medium","topic":"உச்ச நீதிமன்றம்"},{"id":367,"subject":"gk","testNumber":4,"question":"இந்திய உச்ச நீதிமன்றத்தின் தலைமை நீதிபதி மற்றும் பிற நீதிபதிகளை நியமிப்பவர் யார் மற்றும் அவர்களின் ஓய்வு பெறும் வயது என்ன?","options":["குடியரசுத் தலைவர்; 62 வயது","நாடாளுமன்றம்; 65 வயது","குடியரசுத் தலைவர்; 65 வயது","பிரதமர்; 62 வயது"],"correctAnswer":2,"explanation":"உச்ச நீதிமன்றத்தின் தலைமை நீதிபதி மற்றும் பிற நீதிபதிகளைக் குடியரசுத் தலைவர் நியமிக்கிறார். உச்ச நீதிமன்ற நீதிபதிகள் 65 வயது நிறைவடையும் வரை பதவியில் இருப்பார்கள்.","difficulty":"easy","topic":"உச்ச நீதிமன்றம்"},{"id":368,"subject":"gk","testNumber":4,"question":"அரசியலமைப்பின் பாதுகாவலனாகச் செயல்படும் உச்ச நீதிமன்றத்தின் 'நீதிப்புனராய்வு' (Judicial Review) அதிகாரம் என்பது எதைக் குறிக்கிறது?","options":["மாநில எல்லைகளை மாற்றியமைக்கும் அதிகாரம்","அரசியலமைப்புக்கு முரணான சட்டங்களைச் செல்லாது என அறிவிக்கும் அதிகாரம்","குடியரசுத் தலைவரைத் தேர்ந்தெடுக்கும் அதிகாரம்","மத்திய வரவு-செலவுத் திட்டத்திற்கு ஒப்புதல் அளிக்கும் அதிகாரம்"],"correctAnswer":1,"explanation":"மத்திய நாடாளுமன்றம் அல்லது மாநில சட்டமன்றங்கள் இயற்றும் சட்டங்களும் நிர்வாக உத்தரவுகளும் அரசியலமைப்பு விதிகளுக்கு முரணாக இருந்தால் அவற்றைச் செல்லாது என அறிவிக்கும் உச்ச நீதிமன்றத்தின் அதிகாரம் 'நீதிப்புனராய்வு' எனப்படும். இது அரசியலமைப்பின் மேலாதிக்கத்தைப் பாதுகாக்கிறது.","difficulty":"medium","topic":"உச்ச நீதிமன்றம்"},{"id":369,"subject":"gk","testNumber":4,"question":"பொது முக்கியத்துவம் வாய்ந்த சட்டம் அல்லது நிகழ்வு குறித்த பிரச்சினையில் குடியரசுத் தலைவர் உச்ச நீதிமன்றத்தின் ஆலோசனையைக் கோரும் அதிகாரம் எந்தச் சட்டப்பிரிவின் கீழ் உள்ளது?","options":["சட்டப்பிரிவு 131","சட்டப்பிரிவு 129","சட்டப்பிரிவு 136","சட்டப்பிரிவு 143"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 143 உச்ச நீதிமன்றத்தின் 'ஆலோசனை அதிகார வரம்பை' (Advisory Jurisdiction) வழங்குகிறது. இதன்படி பொது முக்கியத்துவம் வாய்ந்த சட்டப் பிரச்சினைகளில் குடியரசுத் தலைவர் உச்ச நீதிமன்றத்தின் கருத்தைக் கேட்கலாம்; ஆனால் அவ்வாலோசனை குடியரசுத் தலைவரைக் கட்டுப்படுத்தாது.","difficulty":"hard","topic":"உச்ச நீதிமன்றம்"},{"id":370,"subject":"gk","testNumber":4,"question":"மத்திய அரசுக்கும் மாநில அரசுகளுக்கும் இடையே அல்லது இரண்டு அல்லது அதற்கு மேற்பட்ட மாநிலங்களுக்கு இடையே ஏற்படும் சிக்கல்களை விசாரிக்கும் உச்ச நீதிமன்றத்தின் அதிகாரம் எது?","options":["ஆலோசனை அதிகார வரம்பு (Advisory Jurisdiction - பிரிவு 143)","நீதிப்பேராணை அதிகார வரம்பு (Writ Jurisdiction - பிரிவு 32)","தனக்கே உரிய அதிகார வரம்பு (Original Jurisdiction - பிரிவு 131)","மேல்முறையீட்டு அதிகார வரம்பு (Appellate Jurisdiction - பிரிவு 132)"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 131-இன் கீழ் மத்திய அரசுக்கும் மாநிலங்களுக்கும் இடையிலான அல்லது மாநிலங்களுக்கு இடையிலான கூட்டாட்சி தொடர்பான வழக்குகளை நேரடியாக விசாரிக்கும் தனிப்பட்ட அதிகாரம் உச்ச நீதிமன்றத்திற்கு மட்டுமே உள்ளது. இது 'தனக்கே உரிய அதிகார வரம்பு' (Original Jurisdiction) எனப்படுகிறது.","difficulty":"hard","topic":"உச்ச நீதிமன்றம்"},{"id":371,"subject":"gk","testNumber":4,"question":"மாநிலத்தின் நிர்வாகத் தலைவரான ஆளுநரை நியமிப்பவர் யார் மற்றும் ஆளுநராக நியமிக்கப்படத் தேவையான குறைந்தபட்ச வயது என்ன?","options":["முதலமைச்சர்; 30 வயது","உயர் நீதிமன்றத் தலைமை நீதிபதி; 30 வயது","பிரதமர்; 35 வயது","குடியரசுத் தலைவர்; 35 வயது"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 155-இன்படி மாநில ஆளுநர் இந்தியக் குடியரசுத் தலைவரால் நியமிக்கப்படுகிறார். சட்டப்பிரிவு 157-இன்படி ஆளுநராக நியமிக்கப்படுபவர் இந்தியக் குடிமகனாகவும் 35 வயது நிரம்பியவராகவும் இருக்க வேண்டும்.","difficulty":"easy","topic":"மாநில அரசு"},{"id":372,"subject":"gk","testNumber":4,"question":"மாநில சட்டமன்றம் கூட்டத்தொடரில் இல்லாதபோது மாநில ஆளுநர் அவசரச் சட்டம் (Ordinance) பிறப்பிக்க அதிகாரம் வழங்கும் சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 213","சட்டப்பிரிவு 123","சட்டப்பிரிவு 161","சட்டப்பிரிவு 226"],"correctAnswer":0,"explanation":"சட்டப்பிரிவு 213-இன்படி மாநில சட்டமன்றம் கூட்டத்தொடரில் இல்லாதபோது உடனடித் தேவைக்காக ஆளுநர் அவசரச் சட்டத்தைப் பிறப்பிக்கலாம். மாநில சட்டமன்றம் மீண்டும் கூடிய 6 வாரங்களுக்குள் அச்சட்டத்திற்கு ஒப்புதல் பெற வேண்டும்.","difficulty":"medium","topic":"மாநில அரசு"},{"id":373,"subject":"gk","testNumber":4,"question":"மாநில முதலமைச்சரை நியமிப்பவர் யார் மற்றும் மாநில அமைச்சரவை கூட்டுப் பொறுப்புடன் யாருக்குப் பொறுப்புடையதாக உள்ளது?","options":["ஆளுநர்; மாநில சட்டமன்றப் பேரவைக்கு","குடியரசுத் தலைவர்; மாநில ஆளுநருக்கு","ஆளுநர்; மாநில ஆளுநருக்கு மட்டுமே","சபாநாயகர்; மாநில சட்டமேலவைக்கு"],"correctAnswer":0,"explanation":"சட்டப்பிரிவு 164-இன்படி மாநில சட்டமன்றப் பேரவையில் பெரும்பான்மை பெற்ற கட்சியின் தலைவரை ஆளுநர் முதலமைச்சராக நியமிக்கிறார். முதலமைச்சர் தலைமையிலான மாநில அமைச்சரவை கூட்டுப் பொறுப்புடன் மாநில சட்டமன்றப் பேரவைக்குப் (Legislative Assembly) பொறுப்புடையதாகும்.","difficulty":"easy","topic":"மாநில அரசு"},{"id":374,"subject":"gk","testNumber":4,"question":"சட்டப்பிரிவு 170-இன்படி ஒரு மாநில சட்டமன்றப் பேரவையின் (Legislative Assembly) அதிகபட்ச மற்றும் குறைந்தபட்ச உறுப்பினர் எண்ணிக்கை முறையே என்ன?","options":["அதிகபட்சம் 250 மற்றும் குறைந்தபட்சம் 60","அதிகபட்சம் 400 மற்றும் குறைந்தபட்சம் 40","அதிகபட்சம் 550 மற்றும் குறைந்தபட்சம் 50","அதிகபட்சம் 500 மற்றும் குறைந்தபட்சம் 60"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 170-இன்படி ஒரு மாநில சட்டமன்றப் பேரவையில் அதிகபட்சம் 500 உறுப்பினர்களும் குறைந்தபட்சம் 60 உறுப்பினர்களும் இருக்கலாம். இருப்பினும் கோவா, சிக்கிம், மிசோரம் போன்ற சிறிய மாநிலங்களுக்குச் சிறப்பு விதிவிலக்கு வழங்கப்பட்டுள்ளது; தமிழ்நாடு சட்டமன்றப் பேரவையில் 234 தொகுதிகள் உள்ளன.","difficulty":"medium","topic":"மாநில அரசு"},{"id":375,"subject":"gk","testNumber":4,"question":"தமிழ்நாடு சட்டமன்ற மேலவை (Legislative Council) எந்த ஆண்டு நீக்கப்பட்டது?","options":["1991 நவம்பர் 1","1986 நவம்பர் 1","1976 நவம்பர் 1","1969 நவம்பர் 1"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 169-இன் கீழ் மாநில சட்டமன்ற மேலவையை உருவாக்கவோ அல்லது நீக்கவோ நாடாளுமன்றத்திற்கு அதிகாரம் உண்டு. இதன்படி 1986-ஆம் ஆண்டு இயற்றப்பட்ட தமிழ்நாடு சட்டமன்ற மேலவை (நீக்கம்) சட்டத்தின் மூலம் 1986 நவம்பர் 1 முதல் தமிழ்நாடு சட்டமன்ற மேலவை நீக்கப்பட்டது.","difficulty":"medium","topic":"மாநில அரசு"},{"id":376,"subject":"gk","testNumber":4,"question":"இந்தியாவின் மிகப் பழமையான உயர் நீதிமன்றங்களில் ஒன்றான சென்னை உயர் நீதிமன்றம் எந்த ஆண்டு நிறுவப்பட்டது?","options":["1866","1858","1862","1875"],"correctAnswer":2,"explanation":"1861-ஆம் ஆண்டு இந்திய உயர் நீதிமன்றங்கள் சட்டத்தின் கீழ் விக்டோரியா மகாராணி வழங்கிய காப்புரிமைக் கடிதத்தின்படி 1862-ஆம் ஆண்டு சென்னை, கல்கத்தா மற்றும் பம்பாய் ஆகிய மூன்று இடங்களில் உயர் நீதிமன்றங்கள் நிறுவப்பட்டன. சென்னை உயர் நீதிமன்றம் 1862 ஆகஸ்ட் 15 அன்று செயல்படத் தொடங்கியது.","difficulty":"easy","topic":"உயர் நீதிமன்றம்"},{"id":377,"subject":"gk","testNumber":4,"question":"உயர் நீதிமன்ற நீதிபதிகளின் ஓய்வு பெறும் வயது என்ன மற்றும் உயர் நீதிமன்றம் நீதிப்பேராணைகள் (Writs) பிறப்பிக்கும் சட்டப்பிரிவு எது?","options":["62 வயது; சட்டப்பிரிவு 226","65 வயது; சட்டப்பிரிவு 226","60 வயது; சட்டப்பிரிவு 214","65 வயது; சட்டப்பிரிவு 32"],"correctAnswer":0,"explanation":"உயர் நீதிமன்ற நீதிபதிகளின் ஓய்வு பெறும் வயது 62 ஆகும் (15-ஆவது சட்டத்திருத்தம் 1963 மூலம் 60-லிருந்து 62 ஆக உயர்த்தப்பட்டது). சட்டப்பிரிவு 226-இன் கீழ் அடிப்படை உரிமைகள் மற்றும் பிற சட்ட உரிமைகளைப் பாதுகாக்க உயர் நீதிமன்றம் நீதிப்பேராணைகளைப் பிறப்பிக்கிறது.","difficulty":"medium","topic":"உயர் நீதிமன்றம்"},{"id":378,"subject":"gk","testNumber":4,"question":"மத்திய-மாநில உறவுகளை ஆய்வு செய்து மாநில சுயாட்சிக்குப் பரிந்துரைகள் வழங்க 1969-ஆம் ஆண்டு தமிழ்நாடு அரசால் அமைக்கப்பட்ட குழு எது?","options":["ராஜமன்னார் குழு","பூஞ்சி குழு","மண்டல் குழு","சர்க்காரியா குழு"],"correctAnswer":0,"explanation":"1969-ஆம் ஆண்டு தமிழ்நாடு அரசு டாக்டர் பி.வி. ராஜமன்னார் தலைமையில் மூன்று பேர் கொண்ட குழுவை மத்திய-மாநில உறவுகளை ஆய்வு செய்ய அமைத்தது. இக்குழு 1971-இல் தனது அறிக்கையைச் சமர்ப்பித்து, மாநிலங்களுக்கு அதிக அதிகாரங்கள் வழங்கவும் மாநிலங்களுக்கு இடையிலான மன்றத்தை அமைக்கவும் பரிந்துரைத்தது.","difficulty":"medium","topic":"மத்திய-மாநில உறவுகள்"},{"id":379,"subject":"gk","testNumber":4,"question":"மத்திய-மாநில உறவுகள் குறித்து விரிவாக ஆய்வு செய்வதற்காக 1983-ஆம் ஆண்டு மத்திய அரசால் அமைக்கப்பட்ட ஆணையம் எது?","options":["ஸ்வரன் சிங் குழு","அசோக் மேத்தா குழு","ராஜமன்னார் குழு","சர்க்காரியா குழு"],"correctAnswer":3,"explanation":"1983-ஆம் ஆண்டு மத்திய அரசு உச்ச நீதிமன்ற ஓய்வுபெற்ற நீதிபதி ஆர்.எஸ். சர்க்காரியா தலைமையில் சர்க்காரியா ஆணையத்தை அமைத்தது. இக்குழுவின் பரிந்துரையின் அடிப்படையிலேயே 1990-இல் சட்டப்பிரிவு 263-இன் கீழ் மாநிலங்களுக்கு இடையிலான மன்றம் (Inter-State Council) அமைக்கப்பட்டது.","difficulty":"medium","topic":"மத்திய-மாநில உறவுகள்"},{"id":380,"subject":"gk","testNumber":4,"question":"இந்தியாவில் மூன்றடுக்கு பஞ்சாயத்து ராஜ் முறையைப் பரிந்துரைத்த குழு எது மற்றும் 1959 அக்டோபர் 2-இல் இதனை முதன்முதலில் நடைமுறைப்படுத்திய மாநிலம் எது?","options":["பல்வந்த்ராய் மேத்தா குழு; ராஜஸ்தான்","எல்.எம். சிங்வி குழு; தமிழ்நாடு","ஜி.வி.கே. ராவ் குழு; மகாராஷ்டிரா","அசோக் மேத்தா குழு; ஆந்திரப் பிரதேசம்"],"correctAnswer":0,"explanation":"1957-ஆம் ஆண்டு அமைக்கப்பட்ட பல்வந்த்ராய் மேத்தா குழு கிராமப் பஞ்சாயத்து, ஊராட்சி ஒன்றியம் மற்றும் மாவட்ட ஊராட்சி ஆகிய மூன்றடுக்கு பஞ்சாயத்து ராஜ் முறையைப் பரிந்துரைத்தது. 1959 அக்டோபர் 2 அன்று ராஜஸ்தான் மாநிலத்தின் நாகவுர் மாவட்டத்தில் பிரதமர் நேரு இதனைத் தொடங்கி வைத்தார்.","difficulty":"easy","topic":"உள்ளாட்சி அமைப்புகள்"},{"id":381,"subject":"gk","testNumber":4,"question":"மூன்றடுக்கு பஞ்சாயத்து ராஜ் முறைக்குப் பதிலாக மாவட்ட ஊராட்சி மற்றும் மண்டலப் பஞ்சாயத்து ஆகிய 'இரண்டடுக்கு பஞ்சாயத்து ராஜ் முறையைப்' பரிந்துரைத்த குழு எது?","options":["ஜி.வி.கே. ராவ் குழு (1985)","அசோக் மேத்தா குழு (1977)","எல்.எம். சிங்வி குழு (1986)","பல்வந்த்ராய் மேத்தா குழு (1957)"],"correctAnswer":1,"explanation":"1977-ஆம் ஆண்டு ஜனதா அரசால் அமைக்கப்பட்ட அசோக் மேத்தா குழு பஞ்சாயத்து ராஜ் அமைப்புகளை வலுப்படுத்த 132 பரிந்துரைகளை வழங்கியது. அவற்றில் மிக முக்கியமானது மூன்றடுக்கு முறைக்குப் பதிலாக இரண்டடுக்கு முறையை அறிமுகப்படுத்துவதாகும்.","difficulty":"medium","topic":"உள்ளாட்சி அமைப்புகள்"},{"id":382,"subject":"gk","testNumber":4,"question":"1992-ஆம் ஆண்டு 73-ஆவது அரசியலமைப்புச் சட்டத்திருத்தம் எதற்கு அரசியலமைப்பு அந்தஸ்து வழங்கியது மற்றும் எந்த அட்டவணையைப் புதிதாகச் சேர்த்தது?","options":["பஞ்சாயத்து ராஜ் அமைப்புகள்; 11-ஆவது அட்டவணை","நகராட்சிகள்; 12-ஆவது அட்டவணை","கூட்டுறவு சங்கங்கள்; 11-ஆவது அட்டவணை","கட்சித் தாவல் தடை; 10-ஆவது அட்டவணை"],"correctAnswer":0,"explanation":"73-ஆவது அரசியலமைப்புச் சட்டத்திருத்தம் (1992) ஊரக உள்ளாட்சி அமைப்புகளான பஞ்சாயத்து ராஜ் அமைப்புகளுக்கு அரசியலமைப்பு அந்தஸ்து வழங்கியது. இது பகுதி IX (பிரிவுகள் 243 முதல் 243O) மற்றும் 29 துறைகளைக் கொண்ட 11-ஆவது அட்டவணையைச் சேர்த்தது; இது 1993 ஏப்ரல் 24 அன்று நடைமுறைக்கு வந்தது.","difficulty":"easy","topic":"உள்ளாட்சி அமைப்புகள்"},{"id":383,"subject":"gk","testNumber":4,"question":"1992-ஆம் ஆண்டு 74-ஆவது அரசியலமைப்புச் சட்டத்திருத்தம் எந்த அமைப்புகளுடன் தொடர்புடையது மற்றும் எத்தனை துறைகளைக் கொண்ட 12-ஆவது அட்டவணையைச் சேர்த்தது?","options":["மாவட்ட நீதிமன்றங்கள்; 18 துறைகள்","கூட்டுறவு சங்கங்கள்; 22 துறைகள்","கிராமப் பஞ்சாயத்துகள்; 29 துறைகள்","நகர்ப்புற உள்ளாட்சி அமைப்புகள் (நகராட்சிகள்); 18 துறைகள்"],"correctAnswer":3,"explanation":"74-ஆவது அரசியலமைப்புச் சட்டத்திருத்தம் (1992) நகர்ப்புற உள்ளாட்சி அமைப்புகளான பேரூராட்சி, நகராட்சி மற்றும் மாநகராட்சிகளுக்கு அரசியலமைப்பு அந்தஸ்து வழங்கியது. இது பகுதி IXA (பிரிவுகள் 243P முதல் 243ZG) மற்றும் 18 துறைகளைக் கொண்ட 12-ஆவது அட்டவணையைச் சேர்த்தது.","difficulty":"medium","topic":"உள்ளாட்சி அமைப்புகள்"},{"id":384,"subject":"gk","testNumber":4,"question":"அரசியலமைப்புச் சட்டப்பிரிவு 243D-இன்படி பஞ்சாயத்து ராஜ் அமைப்புகளில் பெண்களுக்குக் குறைந்தபட்சம் எத்தனை பங்கு இடஒதுக்கீடு கட்டாயமாக்கப்பட்டுள்ளது?","options":["மூன்றில் ஒரு பங்கு (33.3%)","மூன்றில் இரண்டு பங்கு (66.6%)","ஐந்தில் ஒரு பங்கு (20%)","நான்கில் ஒரு பங்கு (25%)"],"correctAnswer":0,"explanation":"73-ஆவது சட்டத்திருத்தத்தின் சட்டப்பிரிவு 243D-இன்படி அனைத்து நிலை பஞ்சாயத்துகளிலும் மொத்த இடங்களில் குறைந்தபட்சம் மூன்றில் ஒரு பங்கு (33.3%) இடங்கள் பெண்களுக்கு ஒதுக்கப்பட வேண்டும். தமிழ்நாடு உள்ளிட்ட பல மாநிலங்கள் தற்போது உள்ளாட்சி அமைப்புகளில் பெண்களுக்கு 50% இடஒதுக்கீடு வழங்குகின்றன.","difficulty":"medium","topic":"உள்ளாட்சி அமைப்புகள்"},{"id":385,"subject":"gk","testNumber":4,"question":"சட்டப்பிரிவு 243A-இன்படி கிராமப் பஞ்சாயத்துப் பகுதியில் உள்ள வாக்காளர் பட்டியலில் பதிவு செய்யப்பட்ட அனைத்து வாக்காளர்களையும் உள்ளடக்கிய நேரடி மக்களாட்சி அமைப்பு எது?","options":["கிராம சபை","மாவட்டத் திட்டக் குழு","ஊராட்சி ஒன்றியக் குழு","கிராம நிர்வாகக் குழு"],"correctAnswer":0,"explanation":"கிராம சபை என்பது கிராமப் பஞ்சாயத்துப் பகுதியில் வாக்காளர் பட்டியலில் பெயர் பதிவு செய்யப்பட்டுள்ள 18 வயது நிரம்பிய அனைத்து வாக்காளர்களையும் உள்ளடக்கிய நிரந்தர அமைப்பாகும். இது பஞ்சாயத்து ராஜ் அமைப்பின் அடித்தளமாகவும் நேரடி மக்களாட்சியின் வடிவமாகவும் செயல்படுகிறது.","difficulty":"easy","topic":"உள்ளாட்சி அமைப்புகள்"},{"id":386,"subject":"gk","testNumber":4,"question":"சுதந்திரமான மற்றும் நேர்மையான தேர்தல்களை நடத்துவதற்காக 'இந்தியத் தேர்தல் ஆணையம்' எந்தச் சட்டப்பிரிவின் கீழ் அமைக்கப்பட்டுள்ளது?","options":["சட்டப்பிரிவு 324","சட்டப்பிரிவு 338","சட்டப்பிரிவு 280","சட்டப்பிரிவு 315"],"correctAnswer":0,"explanation":"இந்திய அரசியலமைப்பின் பகுதி XV-இல் உள்ள சட்டப்பிரிவு 324-இன் கீழ் இந்தியத் தேர்தல் ஆணையம் 1950 ஜனவரி 25 அன்று அமைக்கப்பட்டது. இதனை நினைவுகூரும் வகையில் ஒவ்வொரு ஆண்டும் ஜனவரி 25 'தேசிய வாக்காளர் தினமாக' கொண்டாடப்படுகிறது.","difficulty":"easy","topic":"அரசியலமைப்பு அமைப்புகள்"},{"id":387,"subject":"gk","testNumber":4,"question":"'பொதுப் பணத்தின் பாதுகாவலன்' என்று அழைக்கப்படும் இந்தியக் கணக்குத் தணிக்கையாளர் மற்றும் தலைமைத் தணிக்கையாளர் (CAG) எந்தச் சட்டப்பிரிவின் கீழ் நியமிக்கப்படுகிறார்?","options":["சட்டப்பிரிவு 76","சட்டப்பிரிவு 280","சட்டப்பிரிவு 324","சட்டப்பிரிவு 148"],"correctAnswer":3,"explanation":"சட்டப்பிரிவு 148-இன் கீழ் இந்தியக் கணக்குத் தணிக்கையாளர் மற்றும் தலைமைத் தணிக்கையாளர் (Comptroller and Auditor General of India - CAG) குடியரசுத் தலைவரால் நியமிக்கப்படுகிறார். மத்திய மற்றும் மாநில அரசுகளின் வரவு-செலவுக் கணக்குகளைத் தணிக்கை செய்யும் இவரது பதவிக்காலம் 6 ஆண்டுகள் அல்லது 65 வயது ஆகும்.","difficulty":"medium","topic":"அரசியலமைப்பு அமைப்புகள்"},{"id":388,"subject":"gk","testNumber":4,"question":"இந்திய அரசின் மிக உயர்ந்த சட்ட அலுவலரான 'இந்திய அரசின் தலைமை வழக்கறிஞர்' (Attorney General of India) எந்தச் சட்டப்பிரிவின் கீழ் நியமிக்கப்படுகிறார்?","options":["சட்டப்பிரிவு 124","சட்டப்பிரிவு 148","சட்டப்பிரிவு 76","சட்டப்பிரிவு 165"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 76-இன் கீழ் உச்ச நீதிமன்ற நீதிபதியாவதற்குத் தகுதியுடைய ஒருவரைக் குடியரசுத் தலைவர் இந்திய அரசின் தலைமை வழக்கறிஞராக (Attorney General of India) நியமிக்கிறார். இவர் நாடாளுமன்றத்தின் இரு அவைகளிலும் பங்கேற்றுப் பேச உரிமை உடையவர்; ஆனால் வாக்களிக்க உரிமை இல்லை.","difficulty":"medium","topic":"அரசியலமைப்பு அமைப்புகள்"},{"id":389,"subject":"gk","testNumber":4,"question":"மத்திய அரசுப் பணியாளர் தேர்வாணையம் (UPSC) மற்றும் தமிழ்நாடு அரசுப் பணியாளர் தேர்வாணையம் (TNPSC) போன்ற மாநில தேர்வாணையங்களை அமைப்பதற்கான சட்டப்பிரிவு எது?","options":["சட்டப்பிரிவு 315","சட்டப்பிரிவு 312","சட்டப்பிரிவு 280","சட்டப்பிரிவு 324"],"correctAnswer":0,"explanation":"அரசியலமைப்பின் பகுதி XIV-இல் உள்ள சட்டப்பிரிவு 315 மத்திய அரசிற்கான தேர்வாணையம் (UPSC) மற்றும் மாநிலங்களுக்கான அரசுப் பணியாளர் தேர்வாணையங்களை (SPSC / TNPSC) அமைக்க வழிவகை செய்கிறது. UPSC தலைவர் மற்றும் உறுப்பினர்களைக் குடியரசுத் தலைவரும், TNPSC தலைவர் மற்றும் உறுப்பினர்களை மாநில ஆளுநரும் நியமிக்கின்றனர்.","difficulty":"medium","topic":"அரசியலமைப்பு அமைப்புகள்"},{"id":390,"subject":"gk","testNumber":4,"question":"மத்திய மற்றும் மாநில அரசுகளுக்கு இடையே வரி வருவாயைப் பகிர்ந்தளிக்கப் பரிந்துரைக்கும் 'நிதி ஆணையம்' (Finance Commission) எந்தச் சட்டப்பிரிவின் கீழ் எத்தனை ஆண்டுகளுக்கு ஒருமுறை அமைக்கப்படுகிறது?","options":["சட்டப்பிரிவு 263; 5 ஆண்டுகளுக்கு ஒருமுறை","சட்டப்பிரிவு 324; 6 ஆண்டுகளுக்கு ஒருமுறை","சட்டப்பிரிவு 280; 5 ஆண்டுகளுக்கு ஒருமுறை","சட்டப்பிரிவு 280; 3 ஆண்டுகளுக்கு ஒருமுறை"],"correctAnswer":2,"explanation":"சட்டப்பிரிவு 280-இன் கீழ் குடியரசுத் தலைவர் 5 ஆண்டுகளுக்கு ஒருமுறை ஒரு தலைவர் மற்றும் 4 உறுப்பினர்களைக் கொண்ட நிதி ஆணையத்தை அமைக்கிறார். முதல் நிதி ஆணையம் 1951-இல் கே.சி. நியோகி தலைமையில் அமைக்கப்பட்டது.","difficulty":"easy","topic":"அரசியலமைப்பு அமைப்புகள்"},{"id":391,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பில் மிக விரிவான மாற்றங்களைச் செய்ததால் 'சிறு அரசியலமைப்பு' (Mini Constitution) என்று அழைக்கப்படும் சட்டத்திருத்தம் எது?","options":["73-ஆவது சட்டத்திருத்தம் (1992)","42-ஆவது சட்டத்திருத்தம் (1976)","44-ஆவது சட்டத்திருத்தம் (1978)","86-ஆவது சட்டத்திருத்தம் (2002)"],"correctAnswer":1,"explanation":"1976-ஆம் ஆண்டு இயற்றப்பட்ட 42-ஆவது அரசியலமைப்புச் சட்டத்திருத்தம் முகவுரைத் திருத்தம், அடிப்படைக் கடமைகள் சேர்ப்பு மற்றும் பல பகுதி மாற்றங்களைக் கொண்டுவந்ததால் 'சிறு அரசியலமைப்பு' என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"முக்கிய சட்டத்திருத்தங்கள்"},{"id":392,"subject":"gk","testNumber":4,"question":"மக்களவை மற்றும் மாநில சட்டமன்றத் தேர்தல்களில் வாக்களிக்கும் வயதை 21-லிருந்து 18 ஆகக் குறைத்த அரசியலமைப்புச் சட்டத்திருத்தம் எது?","options":["61-ஆவது சட்டத்திருத்தம் (1988)","52-ஆவது சட்டத்திருத்தம் (1985)","73-ஆவது சட்டத்திருத்தம் (1992)","44-ஆவது சட்டத்திருத்தம் (1978)"],"correctAnswer":0,"explanation":"1988-ஆம் ஆண்டு 61-ஆவது அரசியலமைப்புச் சட்டத்திருத்தம் சட்டப்பிரிவு 326-ஐத் திருத்தி வாக்களிக்கும் வயதை 21-லிருந்து 18 ஆகக் குறைத்தது. இத்திருத்தம் 1989 மார்ச் 28 அன்று நடைமுறைக்கு வந்தது.","difficulty":"easy","topic":"முக்கிய சட்டத்திருத்தங்கள்"},{"id":393,"subject":"gk","testNumber":4,"question":"இந்தியா முழுவதும் ஒரே மாதிரியான மறைமுக வரி முறையான சரக்கு மற்றும் சேவை வரியை (GST) அறிமுகப்படுத்திய அரசியலமைப்புச் சட்டத்திருத்தம் எது?","options":["101-ஆவது சட்டத்திருத்தம்","99-ஆவது சட்டத்திருத்தம்","102-ஆவது சட்டத்திருத்தம்","100-ஆவது சட்டத்திருத்தம்"],"correctAnswer":0,"explanation":"2016-ஆம் ஆண்டு 101-ஆவது அரசியலமைப்புச் சட்டத்திருத்தத்தின் மூலம் சரக்கு மற்றும் சேவை வரி (GST) மற்றும் GST கவுன்சில் (சட்டப்பிரிவு 279A) ஆகியவை அறிமுகப்படுத்தப்பட்டன. நாடு முழுவதும் GST வரி முறை 2017 ஜூலை 1 முதல் நடைமுறைக்கு வந்தது.","difficulty":"medium","topic":"முக்கிய சட்டத்திருத்தங்கள்"},{"id":394,"subject":"gk","testNumber":4,"question":"இந்திய அரசியலமைப்பைத் திருத்துவதற்கான நாடாளுமன்றத்தின் அதிகாரம் மற்றும் நடைமுறை எந்தப் பகுதி மற்றும் சட்டப்பிரிவில் இடம்பெற்றுள்ளது?","options":["பகுதி XVIII, சட்டப்பிரிவு 352","பகுதி XVII, சட்டப்பிரிவு 343","பகுதி XV, சட்டப்பிரிவு 324","பகுதி XX, சட்டப்பிரிவு 368"],"correctAnswer":3,"explanation":"அரசியலமைப்பின் பகுதி XX-இல் உள்ள சட்டப்பிரிவு 368 அரசியலமைப்புச் சட்டத்திருத்த நடைமுறைகளை விளக்குகிறது. இதன்படி சாதாரணப் பெரும்பான்மை, சிறப்புப் பெரும்பான்மை மற்றும் சிறப்புப் பெரும்பான்மையுடன் பாதி மாநில சட்டமன்றங்களின் ஒப்புதல் என மூன்று வகைகளில் திருத்தங்கள் மேற்கொள்ளப்படுகின்றன.","difficulty":"medium","topic":"முக்கிய சட்டத்திருத்தங்கள்"},{"id":395,"subject":"gk","testNumber":4,"question":"தகவல் அறியும் உரிமைச் சட்டம் (RTI) எப்போது நடைமுறைக்கு வந்தது மற்றும் சாதாரண சூழ்நிலையில் பொதுத் தகவல் அலுவலர் எத்தனை நாட்களுக்குள் தகவலை வழங்க வேண்டும்?","options":["2005 அக்டோபர் 12; 30 நாட்கள்","2002 அக்டோபர் 12; 15 நாட்கள்","2009 ஏப்ரல் 1; 30 நாட்கள்","2005 ஜனவரி 26; 45 நாட்கள்"],"correctAnswer":0,"explanation":"அரசு நிர்வாகத்தில் வெளிப்படைத்தன்மையை உறுதி செய்யும் தகவல் அறியும் உரிமைச் சட்டம் (Right to Information Act) 2005-இல் இயற்றப்பட்டு 2005 அக்டோபர் 12 அன்று முழுமையாக நடைமுறைக்கு வந்தது. விண்ணப்பம் பெற்ற 30 நாட்களுக்குள் (உயிர் அல்லது சுதந்திரம் தொடர்பானதாயின் 48 மணி நேரத்திற்குள்) தகவல் வழங்கப்பட வேண்டும்.","difficulty":"medium","topic":"சட்டரீதியான அமைப்புகள் & சட்டங்கள்"},{"id":396,"subject":"gk","testNumber":4,"question":"பொது ஊழியர்களுக்கு எதிரான ஊழல் புகார்களை விசாரிக்க 'லோக்பால் மற்றும் லோக்ஆயுக்தா சட்டம்' எந்த ஆண்டு இயற்றப்பட்டது மற்றும் இந்தியாவின் முதல் லோக்பால் தலைவர் யார்?","options":["2013; நீதிபதி பினாகி சந்திர கோஷ்","2010; நீதிபதி என். சந்தோஷ் ஹெக்டே","2011; நீதிபதி ஏ.எம். கான்வில்கர்","2014; நீதிபதி ரஞ்சன் கோகோய்"],"correctAnswer":0,"explanation":"மத்திய அளவில் லோக்பால் மற்றும் மாநில அளவில் லோக்ஆயுக்தா அமைப்புகளை உருவாக்க 2013-ஆம் ஆண்டு லோக்பால் மற்றும் லோக்ஆயுக்தா சட்டம் இயற்றப்பட்டது. உச்ச நீதிமன்ற ஓய்வுபெற்ற நீதிபதி பினாகி சந்திர கோஷ் 2019-ஆம் ஆண்டு இந்தியாவின் முதல் லோக்பால் தலைவராக நியமிக்கப்பட்டார்.","difficulty":"hard","topic":"சட்டரீதியான அமைப்புகள் & சட்டங்கள்"},{"id":397,"subject":"gk","testNumber":4,"question":"தேசிய மனித உரிமைகள் ஆணையம் (NHRC) எந்தச் சட்டத்தின் கீழ் எப்போது அமைக்கப்பட்டது?","options":["தகவல் உரிமைச் சட்டம் 2005; 2005 அக்டோபர் 12","இந்திய அரசியலமைப்புப் பிரிவு 338; 1990 அக்டோபர் 12","மனித உரிமைகள் பாதுகாப்புச் சட்டம் 1993; 1993 அக்டோபர் 12","குடிமை உரிமைகள் பாதுகாப்புச் சட்டம் 1955; 1995 டிசம்பர் 10"],"correctAnswer":2,"explanation":"தேசிய மனித உரிமைகள் ஆணையம் (NHRC) என்பது ஒரு சட்டரீதியான (Statutory) அமைப்பாகும். இது 1993-ஆம் ஆண்டு மனித உரிமைகள் பாதுகாப்புச் சட்டத்தின் கீழ் 1993 அக்டோபர் 12 அன்று அமைக்கப்பட்டது; இதன் தலைமையகம் புதுடெல்லியில் உள்ளது.","difficulty":"hard","topic":"சட்டரீதியான அமைப்புகள் & சட்டங்கள்"},{"id":398,"subject":"gk","testNumber":4,"question":"இந்தியாவிலேயே முதன்முதலில் நிறுவப்பட்ட மாநகராட்சி (Municipal Corporation) எது மற்றும் அது எந்த ஆண்டு நிறுவப்பட்டது?","options":["சென்னை மாநகராட்சி; 1688","பம்பாய் மாநகராட்சி; 1726","கல்கத்தா மாநகராட்சி; 1726","டெல்லி மாநகராட்சி; 1882"],"correctAnswer":0,"explanation":"இந்தியாவின் முதல் மாநகராட்சி 1688-ஆம் ஆண்டு சென்னையில் (மதராஸ் மாநகராட்சி) நிறுவப்பட்டது. பின்னர் 1726-இல் பம்பாய் மற்றும் கல்கத்தா மாநகராட்சிகள் அமைக்கப்பட்டன; லார்ட் ரிப்பன் 'இந்திய உள்ளாட்சி அமைப்புகளின் தந்தை' என அழைக்கப்படுகிறார்.","difficulty":"hard","topic":"உள்ளாட்சி அமைப்புகள்"},{"id":399,"subject":"gk","testNumber":4,"question":"இந்தியாவின் தலைமைத் தேர்தல் ஆணையர் மற்றும் பிற தேர்தல் ஆணையர்களின் பதவிக்காலம் என்ன?","options":["5 ஆண்டுகள் அல்லது 65 வயது (எது முந்தையதோ அது)","6 ஆண்டுகள் அல்லது 65 வயது (எது முந்தையதோ அது)","6 ஆண்டுகள் அல்லது 62 வயது (எது முந்தையதோ அது)","5 ஆண்டுகள் அல்லது 62 வயது (எது முந்தையதோ அது)"],"correctAnswer":1,"explanation":"இந்தியத் தேர்தல் ஆணையம் ஒரு தலைமைத் தேர்தல் ஆணையர் மற்றும் இரண்டு தேர்தல் ஆணையர்களைக் கொண்ட பல உறுப்பினர் அமைப்பாகும். இவர்களின் பதவிக்காலம் 6 ஆண்டுகள் அல்லது 65 வயது நிறைவடையும் வரை (இதில் எது முந்தையதோ அது) ஆகும்.","difficulty":"hard","topic":"அரசியலமைப்பு அமைப்புகள்"},{"id":400,"subject":"gk","testNumber":4,"question":"மாநில அரசின் மிக உயர்ந்த சட்ட அலுவலரான 'மாநில அரசின் தலைமை வழக்கறிஞர்' (Advocate General of the State) எந்தச் சட்டப்பிரிவின் கீழ் ஆளுநரால் நியமிக்கப்படுகிறார்?","options":["சட்டப்பிரிவு 155","சட்டப்பிரிவு 165","சட்டப்பிரிவு 217","சட்டப்பிரிவு 76"],"correctAnswer":1,"explanation":"சட்டப்பிரிவு 165-இன் கீழ் உயர் நீதிமன்ற நீதிபதியாவதற்குத் தகுதியுடைய ஒருவரை மாநில ஆளுநர் மாநில அரசின் தலைமை வழக்கறிஞராக (Advocate General) நியமிக்கிறார். இவர் மாநில சட்டமன்ற நடவடிக்கைகளில் பங்கேற்றுப் பேச உரிமை பெற்றவர்; ஆனால் வாக்களிக்கும் உரிமை கிடையாது.","difficulty":"hard","topic":"அரசியலமைப்பு அமைப்புகள்"}]);
